INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_6325660489', 'Dive Seenigama Dive Lanka', 'attraction', 'Ancient traditions, Kandy Period', 'While ''Dive Seenigama Dive Lanka'' is a modern establishment, its name and location are intrinsically linked to the historically significant Seenigama area. This coastal region is renowned for the ancient Seenigama Devalaya, an island temple dedicated to the guardian deity Dedimunda Deviyo, a site of pilgrimage and unique traditional rituals for centuries.', 'The Seenigama Devalaya, the historical heart of the area, is situated on a small rocky island and features traditional Sri Lankan temple architecture. Its shrines, dedicated to Dedimunda Deviyo, typically incorporate white-washed walls and tiled roofs, reflecting styles common in post-Kandy period temple construction, though specific ancient structures have undergone renovations over time.', 'The Seenigama area, through its revered Devalaya, holds profound cultural significance as a center for traditional Sri Lankan spiritual practices, particularly the ''dehi kapima'' (lime cutting) ritual. It symbolizes justice and protection, attracting devotees who seek divine intervention and making it a unique expression of folk religion and cultural identity in Sri Lanka.', '["Seenigama","Island Temple","Dedimunda Deviyo","Rituals","Folk Religion","Coastal Heritage","Pilgrimage Site","Hikkaduwa Area"]', 'See-ni-ga-ma Dee-va Lank-a, De-di-mun-da De-vi-yo, De-hi Ka-pi-ma', 'Modern dive center, Seenigama historical area, island temple, Dedimunda Deviyo, justice rituals', 6.1583507, 80.0919254);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_4556181993', 'Turtle sanctuary', 'attraction', 'Contemporary Conservation', 'Sri Lanka''s coastline is a vital nesting ground for several species of sea turtles, leading to the establishment of sanctuaries for their protection. These facilities primarily focus on rescuing injured turtles, rehabilitating them, and operating hatcheries to increase the survival rate of hatchlings before their release into the ocean.', 'Simple, functional structures comprising concrete holding tanks, shaded enclosures for hatchlings and injured turtles, and basic visitor information centers. Construction materials are typically local and practical, focusing on utility rather than elaborate design.', 'These sanctuaries play a crucial role in the conservation of endangered sea turtle species native to Sri Lankan waters. They contribute significantly to marine biodiversity protection, environmental education, and sustainable eco-tourism, highlighting Sri Lanka''s commitment to natural heritage.', '["Wildlife Conservation","Sea Turtles","Eco-tourism","Marine Life","Rehabilitation Center","Hatchery","Environmental Education"]', 'Tur-tle Sanc-tu-a-ry', 'Sea turtle conservation, rehabilitation center, eco-tourism, educational site, marine biodiversity', 6.1671685, 80.0884684);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_6347257887', 'Tsunami Monument', 'monument', 'Contemporary (21st Century)', 'The Tsunami Monument stands as a solemn memorial to the thousands of lives lost in Sri Lanka during the devastating 2004 Indian Ocean tsunami. It serves as a poignant reminder of the tragedy and a tribute to the resilience of the affected communities.', 'Constructed primarily from concrete, the monument often features an abstract, wave-like form, symbolizing the destructive power of the tsunami. Its modern design emphasizes remembrance and reflection rather than traditional Sri Lankan architectural styles.', 'This site holds profound cultural significance as a national symbol of grief, remembrance, and the enduring spirit of the Sri Lankan people in the face of immense natural disaster. It also highlights the global solidarity and aid received during the recovery period.', '["Tsunami Memorial","2004 Disaster","Remembrance Site","Modern Monument","Coastal Sri Lanka","Natural Disaster","Galle Landmark","Resilience Symbol"]', 'Tsoo-nah-mee Mon-yoo-ment', 'Commemorates 2004 tsunami, Located in Galle, Symbol of remembrance, Modern concrete structure, Represents national resilience', 6.1665372, 80.0892894);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_3377399101', 'Clippenburg Bastion', 'archaeological_site', 'Dutch Colonial', 'Clippenburg Bastion is a key defensive structure of the historic Galle Fort, built by the Dutch during their colonial rule in the 17th century. Strategically positioned, it guarded the northern approach to the harbor, protecting the vital port from naval attacks. It stands as a testament to the extensive fortifications that secured Dutch interests in Ceylon.', 'Constructed primarily from coral, granite, and laterite, bound with lime mortar, the bastion exemplifies 17th-century European military engineering. Its robust, angular form with thick walls and gun emplacements was designed to withstand cannon fire and provide commanding views over the harbor entrance.', 'As an integral part of the UNESCO World Heritage-listed Galle Fort, Clippenburg Bastion represents a significant period of Sri Lanka''s colonial past and its strategic importance in maritime trade. It showcases the enduring architectural legacy of European powers and contributes to the fort''s global recognition as a well-preserved fortified city.', '["Galle Fort","Dutch Colonial","Bastion","Fortification","Archaeological Site","Maritime History","UNESCO Heritage","17th Century"]', 'Clip-pen-burg Bas-tion', 'Dutch colonial, Galle Fort, 17th century, defensive structure, UNESCO site', 6.0270001, 80.2140301);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_11502316371', 'Elephant riding', 'attraction', 'Ancient to Modern Era', 'Elephants have held a revered position in Sri Lankan history for millennia, serving in royal processions, warfare, and heavy labor. While their traditional roles have evolved, elephant riding has emerged as a contemporary tourist attraction, offering visitors a unique interaction with these majestic animals.', 'The activity of elephant riding does not involve permanent architectural structures. Historically, temporary platforms or simple wooden howdahs were crafted from timber and textiles for carrying riders, designed for function rather than architectural style.', 'Elephants are deeply embedded in Sri Lankan culture, symbolizing strength, wisdom, and prosperity. They play a vital role in religious festivals, particularly the Esala Perahera, and represent a living link to the island''s rich heritage and natural biodiversity.', '["Elephant experience","Wildlife interaction","Cultural heritage","Sri Lankan elephants","Tourism attraction","Historical practice","Animal encounter"]', 'El-uh-fuhnt Ry-ding', 'Historical elephant use, Cultural significance, Modern tourism attraction', 6.0901532, 80.1728791);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_4556165692', 'Wijala beach', 'attraction', 'Contemporary', 'Wijaya Beach is a renowned sandy stretch on Sri Lanka''s southern coast, celebrated for its calm, shallow waters protected by a natural offshore reef. While lacking ancient historical structures, its natural beauty has made it a significant contemporary attraction for both local communities and international tourists. It offers a tranquil environment ideal for swimming and relaxation.', 'As a natural coastal formation, Wijaya Beach features no historical architectural structures. Its defining characteristics are its crescent-shaped sandy shore, the natural coral reef that creates a sheltered lagoon, and the surrounding tropical vegetation.', 'Wijaya Beach holds contemporary cultural significance as a prominent leisure destination, contributing substantially to the local tourism economy. It embodies Sri Lanka''s appeal as a tropical paradise, serving as a gathering place for families and a key highlight for visitors seeking pristine natural beauty and safe ocean activities.', '["Beach","Southern Coast","Tourism","Swimming","Reef","Relaxation","Family-friendly","Natural beauty"]', 'Wi-ja-ya Beach', 'Southern coast, Calm waters, Natural reef, Popular tourist spot, Family-friendly', 5.9996808, 80.2636381);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_5800272353', 'Pallisters', 'attraction', 'British Colonial', 'Pallisters likely refers to a colonial-era bungalow or estate residence, characteristic of the British presence in Sri Lanka''s Southern Province. These buildings served as homes for European planters or administrators, reflecting the social hierarchy and economic activities of the colonial period.', 'Typically constructed with plastered brick or stone walls and timber roofs with clay tiles, these bungalows feature wide verandas, high ceilings, and large windows designed for tropical ventilation. The style often blends European architectural influences like Neoclassical or Victorian with adaptations for the local climate.', 'Such colonial bungalows are significant as tangible reminders of Sri Lanka''s British colonial past, showcasing the architectural legacy and lifestyle of the era. They represent a distinct period of social and economic transformation, contributing to the island''s diverse heritage landscape.', '["British Colonial","Historic Residence","Colonial Architecture","Galle Heritage","Tropical Bungalow","Architectural Landmark","Planter''s Home"]', 'Pal-lis-ters', 'British Colonial, historic residence, architectural heritage, Galle region, tropical design', 5.9862051, 80.3953023);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_5242116921', 'Turtle Bay', 'attraction', 'Natural Heritage', 'Turtle Bay is a natural coastal area, likely named for its historical or ongoing significance as a habitat for sea turtles. While not an archaeological site, its ecological importance contributes significantly to Sri Lanka''s natural heritage and biodiversity.', 'Not applicable, as Turtle Bay is a natural coastal feature defined by its sandy shores, rock formations, and marine environment, rather than man-made structures.', 'Its significance lies in its role as a potential nesting or feeding ground for various species of sea turtles, which are culturally revered and protected in Sri Lanka. It contributes to the nation''s rich biodiversity and eco-tourism appeal, drawing attention to marine conservation efforts.', '["Natural landmark","Coastal","Sea turtles","Biodiversity","Marine life","Eco-tourism","Southern coast"]', 'Tur-tle Bay', 'Natural bay, sea turtle habitat, biodiversity, southern Sri Lanka', 5.9412891, 80.4655387);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_9722122604', 'Hemachandra Gunasekara', 'memorial', 'Post-Independence Sri Lanka', 'This memorial honors Hemachandra Gunasekara, a figure whose contributions are remembered within the local community. While specific national records are limited, such memorials typically commemorate individuals for their service, sacrifice, or significant impact on local life. It serves as a focal point for community remembrance and historical reflection.', 'Often constructed from durable materials like concrete, granite, or marble, these memorials typically feature a commemorative plaque or a bust. The style is generally functional and reverent, reflecting contemporary Sri Lankan memorial design.', 'Memorials like this are vital for preserving local history and identity, fostering community cohesion, and ensuring that significant individuals are not forgotten. They serve as sites for local ceremonies, reinforcing shared values and heritage within the region.', '["Local memorial","Community heritage","Remembrance site","Sri Lankan history","Post-independence era","Public monument"]', 'He-ma-chan-dra Gu-na-se-ka-ra', 'Local memorial, honors Hemachandra Gunasekara, community remembrance, post-independence', 5.9738344, 80.4295665);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_9722124151', 'General Montagu Jayawickrama', 'memorial', 'Post-Independence Sri Lanka (20th Century)', 'This memorial honors Montagu Jayawickrama (1911-2001), a prominent Sri Lankan politician and public servant. He held significant ministerial portfolios, including Justice and Public Administration, and served as Governor of the North Western Province. The memorial commemorates his extensive contributions to national governance and regional development.', 'Typically, memorials for such figures are constructed from durable materials like stone or concrete, often featuring a sculpted bust or an inscribed plaque detailing the individual''s achievements and dates. These monuments are usually placed in public areas, designed for accessibility and public remembrance.', 'Montagu Jayawickrama was a key figure in Sri Lankan politics during the mid to late 20th century, representing the Weligama electorate for many years. His memorial signifies the nation''s recognition of his dedication to public service, his role in shaping post-independence governance, and his impact on the local community.', '["Politician","Public Servant","Post-Independence","Sri Lankan History","Memorial","Matara District","Weligama","Governor"]', 'Mon-ta-gu Ja-ya-wick-ra-ma', 'Sri Lankan politician, Minister of Justice, Governor, Weligama representative, Public service', 5.9738297, 80.429318);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_4620115989', 'Tea factory Hill garden', 'attraction', 'British Colonial', 'Tea factories like Hill Garden emerged during the British Colonial era, playing a pivotal role in processing Ceylon''s burgeoning tea industry. These establishments transformed freshly picked tea leaves into the finished product, driving the island''s economic landscape and global reputation for tea.', 'Typically constructed with durable materials such as brick, concrete, and timber, these multi-story industrial buildings often feature large windows for ventilation and corrugated iron roofs. Their functional design facilitates the gravity-fed tea processing stages, from wilting to drying.', 'Tea factories are central to Sri Lanka''s identity as a premier tea producer, symbolizing the nation''s agricultural heritage and economic backbone. They represent the legacy of colonial enterprise and the enduring global impact of ''Ceylon Tea'', a key export and cultural identifier.', '["Tea industry","Colonial heritage","Agricultural landmark","Sri Lankan tea","Processing plant","Historic factory","Hill country","Economic history"]', 'Tea fac-to-ry Hill Gar-den', 'British Colonial era, tea processing, economic backbone, Ceylon Tea heritage', 6.1556042, 80.2204598);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_4621586590', 'Tea shop-factory', 'attraction', 'British Colonial / Post-Colonial', 'Tea factories emerged in Ceylon during the British Colonial era, transforming the island''s economy and landscape. These establishments were crucial for processing tea leaves, from wilting to drying and grading, for global export. Many continue to operate, blending historical methods with modern practices.', 'Typically constructed with robust materials like brick, timber, and corrugated iron, these factories feature multi-level structures designed for gravity-fed processing. Large windows and open spaces facilitate ventilation and light, characteristic of functional industrial architecture of the period.', 'Tea factories are vital symbols of Sri Lanka''s economic backbone and colonial heritage, representing the island''s global prominence in the tea industry. They embody the legacy of plantation agriculture and the enduring cultural significance of Ceylon Tea.', '["Tea Industry","Colonial Heritage","Sri Lankan Tea","Industrial Architecture","Economic History","Plantation Economy","Tea Processing"]', 'Tee shop-fak-tuh-ree', 'Tea processing, colonial legacy, economic backbone, industrial heritage, Ceylon Tea', 6.1950683, 80.3242);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_osm_node_6273572085', 'Paid Palm Rope Swing', 'attraction', 'Contemporary Sri Lanka', 'This attraction is a contemporary feature, popular with tourists seeking recreational activities along Sri Lanka''s scenic coastlines. It represents a modern adaptation of traditional leisure, offering visitors a unique photo opportunity and experience. Its emergence is tied to the growth of coastal tourism in recent decades.', 'Constructed primarily from natural materials such as sturdy palm trees and durable ropes, often with a simple wooden seat. Its structural form is rudimentary, designed for temporary recreational use rather than permanent architectural significance, emphasizing safety and simplicity.', 'While not a site of ancient heritage, the palm rope swing reflects a contemporary aspect of Sri Lankan tourism, blending local natural resources with recreational demand. It symbolizes the evolving landscape of leisure activities offered to visitors, contributing to the local tourism economy and providing unique photo opportunities.', '["Tourist attraction","Recreational","Coastal activity","Photo spot","Modern leisure","Palm tree swing","Beach experience","Contemporary tourism"]', 'Payd Palm Rohp Swing', 'Modern tourist attraction, recreational activity, popular photo spot, uses natural materials, contributes to local tourism', 6.0013739, 80.2600697);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_sigiriya', 'Sigiriya Rock Fortress', 'archaeological_site', '5th Century AD', 'Sigiriya, the Lion Rock, is a UNESCO World Heritage Site and one of Sri Lanka''s most iconic landmarks. Built by King Kashyapa I (477–495 AD) as a fortified palace atop a 200-meter granite monolith, it stands as one of the most remarkable urban planning feats of the ancient world. After Kashyapa''s defeat, it served as a Buddhist monastery until the 14th century.', 'The fortress features a series of elaborate water gardens at its base, midway rock shelters, mirror wall, ancient frescoes depicting celestial maidens (Apsaras), and the iconic Lion''s Paw gateway carved from the rock face. The summit plateau held a palace with sophisticated cisterns, audience halls, and gardens engineered with remarkable hydraulic precision.', 'Sigiriya represents the pinnacle of ancient Sri Lankan art, architecture, and urban planning. The mirror wall inscriptions dating to the 8th century are among the earliest examples of Sinhalese poetry. The frescoes, painted with mineral-based paints, are living evidence of advanced artistic traditions. It is often called the Eighth Wonder of the Ancient World.', '["historical-monument","UNESCO","Heritage","Archaeological","Cultural Triangle"]', 'Si-gi-ri-ya Rock For-tress', '5th century rock citadel, King Kashyapa, lion gateway, UNESCO World Heritage, ancient frescoes', 7.957, 80.7603);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_pidurangala', 'Pidurangala Rock', 'attraction', '5th Century AD', 'Pidurangala Rock stands just 1.5 km north of Sigiriya and offers one of the best panoramic views of the iconic Lion Rock. The rock houses ancient Buddhist cave temples believed to have been established by King Kashyapa to house the monks displaced from Sigiriya when he converted it to a palace fortress.', 'At the base of Pidurangala lies a cave temple with a large reclining Buddha statue carved from white plaster over a natural rock formation. The cave interiors preserve ancient murals and inscriptions. The summit is a boulder scramble rewarded with 360-degree views spanning the Cultural Triangle.', 'Pidurangala holds dual significance as both an active Buddhist place of worship and a premier trekking destination. Its monastery at the base is still used by monks today, offering a living connection to the ancient Sinhalese Buddhist monastic tradition that flourished under royal patronage.', '["religious-temple","Heritage","Trekking","Cultural Triangle","Buddhist"]', 'Pi-du-ran-ga-la Rock', 'Buddhist cave temple, panoramic views of Sigiriya, ancient murals, trekking destination, 5th century origins', 7.9633, 80.7567);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_dambulla', 'Dambulla Cave Temple', 'religious_site', '1st Century BC', 'The Dambulla Cave Temple, also known as the Golden Temple of Dambulla, is Sri Lanka''s largest and best-preserved cave temple complex. King Valagamba (Vattagamani Abhaya) took refuge here around 100 BC while exiled, and upon reclaiming his throne, transformed the natural caves into magnificent royal rock temples as an act of gratitude.', 'The complex comprises five interconnected caves cut into a 160-meter-high rock outcrop. They house over 150 Buddha statues, three statues of Sri Lankan kings, and four statues of deities including Vishnu and Ganesh. The cave ceilings are entirely covered with an unbroken sweep of paintings spanning 2,100 square meters — the largest area of cave paintings in the world.', 'Dambulla has been a place of continuous Buddhist worship for over 22 centuries, receiving royal patronage from successive kingdoms. It was listed as a UNESCO World Heritage Site in 1991. The giant white Buddha statue at its base and the golden roof visible from miles away make it a beacon of Sri Lankan Buddhist identity.', '["religious-temple","UNESCO","Buddhist","Heritage","Cultural Triangle"]', 'Dam-bul-la Cave Tem-ple', 'UNESCO cave temple, 1st century BC, 150 Buddha statues, largest cave paintings in world, Golden Temple', 7.8568, 80.6491);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_polonnaruwa', 'Polonnaruwa Ancient City', 'archaeological_site', '10th–13th Century AD', 'Polonnaruwa served as the second capital of Sri Lanka after Anuradhapura was abandoned in the 10th century. It flourished as a magnificent royal city under Chola invaders and later under Sinhalese kings, especially Parakramabahu I (1153–1186 AD), who united the entire island under one rule and undertook massive irrigation and construction projects.', 'The ancient city contains royal palace ruins, the Gal Vihara rock sculptures (four magnificent Buddha figures carved from a single granite face), Rankot Vihara stupa, the Lankatilaka image house with its towering brick walls, Vatadage (circular relic house), and the Parakrama Samudraya — a vast artificial reservoir covering 2,400 hectares.', 'Polonnaruwa represents the zenith of medieval Sri Lankan civilization. The Gal Vihara Buddhas are considered masterpieces of ancient sculpture. King Parakramabahu''s philosophy that ''not a drop of water should reach the sea without being made use of by man'' drove irrigation innovation that still benefits farmers today.', '["historical-monument","UNESCO","Archaeological","Heritage","Cultural Triangle"]', 'Po-lon-na-ru-wa An-cient Ci-ty', 'UNESCO World Heritage, medieval capital, Gal Vihara rock sculptures, Parakramabahu I, 12th century golden age', 7.9403, 81.0003);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_anuradhapura', 'Anuradhapura Sacred City', 'archaeological_site', '4th Century BC – 10th Century AD', 'Anuradhapura was the first and longest-reigning capital of Sri Lanka, governing for over 1,300 years. Founded by King Pandukabhaya in 377 BC, it became one of the ancient world''s greatest cities with a population exceeding 100,000. It was a center of Theravada Buddhism and Sinhalese civilization, maintaining diplomatic ties with India, China, and the Mediterranean world.', 'The sacred city contains the Sri Maha Bodhi (the oldest recorded tree in history, planted from a cutting of the original Bodhi tree under which Buddha attained enlightenment in 288 BC), three colossal stupas — Ruwanwelisaya, Jetavanaramaya (once the third tallest structure in the ancient world), and Thuparamaya. The Abhayagiri and Jetavana monasteries each housed thousands of monks.', 'Anuradhapura is one of the holiest cities in Buddhism. The Sri Maha Bodhi draws millions of pilgrims annually. The city demonstrates that ancient Sri Lanka possessed sophisticated urban planning with hydraulic systems, hospitals, and organized city layouts rivaling contemporary Roman cities.', '["religious-temple","UNESCO","Archaeological","Buddhist","Heritage"]', 'A-nu-rad-ha-pu-ra Sa-cred Ci-ty', 'UNESCO heritage, ancient capital 1300 years, Sri Maha Bodhi sacred tree, giant stupas, Theravada Buddhist heartland', 8.3114, 80.3718);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_minneriya', 'Minneriya National Park', 'national_park', 'Ancient to Present', 'Minneriya National Park is built around the ancient Minneriya Tank, one of the largest man-made reservoirs in Sri Lanka, constructed by King Mahasena in the 3rd century AD. The park is world-famous for hosting ''The Gathering'' — the largest congregation of Asian elephants on Earth, with 200–400 wild elephants assembling around the reservoir each dry season.', 'The Minneriya Tank bund (dam), an engineering marvel of ancient Sri Lanka, spans several kilometers and still functions as an active irrigation system after 1,700 years. The surrounding park landscape transitions from scrub forest to grasslands, with the reservoir serving as the ecological anchor for extraordinary wildlife.', 'Beyond its ecological significance, Minneriya embodies Sri Lanka''s ancient water management wisdom. King Mahasena''s 16 reservoirs transformed the Dry Zone into a rice-producing civilization. The elephant gathering is now one of the greatest wildlife spectacles in Asia, attracting naturalists and photographers worldwide.', '["urban-park","Wildlife","Nature","Elephant","Safari"]', 'Min-ner-i-ya Na-tion-al Park', 'World''s largest elephant gathering, 3rd century ancient tank, 400 wild elephants, UNESCO tentative list, dry zone safari', 8.034, 80.8995);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_kandy_tooth', 'Temple of the Tooth Relic', 'religious_site', '16th Century (current structure)', 'The Temple of the Sacred Tooth Relic (Sri Dalada Maligawa) in Kandy is the most sacred Buddhist site in Sri Lanka and one of the holiest in Asia. It houses the left canine tooth of the Buddha, brought to Sri Lanka in the 4th century AD hidden in the hair of an Orissan princess. Whoever possessed the tooth relic was believed to hold the right to rule the island.', 'The current temple complex was largely built during the Kandyan Kingdom era (17th–18th centuries). It features the signature Kandyan architectural style with whitewashed walls, ornate moat (Diyawadana Nilame), gilded canopy over the inner shrine, intricate wood carvings, and the octagonal Patthirippuwa tower built by King Sri Vikrama Rajasinha. The golden roof was added by President Premadasa in 1987.', 'The Esala Perahera festival held here each July–August is one of the grandest Buddhist pageants in the world, featuring 100 elaborately decorated elephants, Kandyan dancers, fire performers, and royal standard bearers processing through Kandy over ten nights. The temple attracts over 3 million visitors annually and is a UNESCO World Heritage Site.', '["religious-temple","UNESCO","Buddhist","Heritage","Hill Country"]', 'Tem-ple of the Tooth Re-lic, Sri Da-la-da Ma-li-ga-wa', 'Sacred Buddha tooth relic, UNESCO World Heritage, Esala Perahera festival, Kandyan architecture, 4th century AD relic', 7.2936, 80.6418);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_nuwara_eliya', 'Nuwara Eliya', 'attraction', 'British Colonial', 'Nuwara Eliya, known as ''Little England,'' sits at 1,868 meters above sea level in Sri Lanka''s central highlands. Discovered by British explorer John Davy in 1819 and developed as a hill station by Governor Sir Edward Barnes, it became the leisure retreat for British colonial administrators escaping Colombo''s heat. The surrounding hills produce some of the world''s finest high-grown Ceylon tea.', 'The town retains remarkable British colonial architecture including the Hill Club (1876, with original Tudor-style interiors), the Grand Hotel (1891, former residence of Governor Sir Edward Barnes), Victoria Park, a Victorian post office, and the Nuwara Eliya Golf Club — the oldest golf club in Asia (1889). The landscape features English-style gardens, hedgerows, and manicured estates.', 'Nuwara Eliya represents an extraordinary preservation of British colonial culture transplanted to a tropical highland. The surrounding tea estates, established from the 1860s onwards, transformed the region''s landscape and economy. Today it hosts the Sri Lanka April Season — a carnival of horse racing, automobile rallying, and social events that preserves Victorian traditions.', '["historical-monument","Heritage","Tea Country","Hill Country","Colonial"]', 'Nu-wa-ra E-li-ya, Little England', 'British colonial hill station, 1868 meters altitude, world-class Ceylon tea, Victorian architecture, April Season festival', 6.9497, 80.7718);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_ella_bridge', 'Ella Nine Arch Bridge', 'attraction', 'British Colonial (1921)', 'The Nine Arch Bridge in Ella, also called the Bridge in the Sky, is one of the most iconic railway viaducts in Asia. Built in 1921 during British colonial rule, it was constructed entirely without steel — using only stone, brick, and cement — because metal was diverted to the war effort during World War I. It spans a dramatic valley surrounded by lush jungle.', 'The bridge stands 24 meters high and spans 91 meters through nine arched spans, each 20 meters wide, built from local stone and brick. Its construction required brilliant engineering given the steep terrain and the prohibition on steel. The bridge carries the Colombo–Badulla main line, one of the most scenic railway routes in the world.', 'The Nine Arch Bridge has become one of Sri Lanka''s most photographed landmarks and is emblematic of the colonial-era engineering ambition that transformed the highlands. Watching a blue-painted train thunder across the arches above a tea valley is considered one of Asia''s great travel experiences. The surrounding area hosts excellent hiking trails through tea estates.', '["historical-monument","Heritage","Hill Country","Railway","Architecture"]', 'El-la Nine Arch Bridge, Bridge in the Sky', '1921 colonial railway bridge, built without steel, nine arches, 24 meters high, iconic tea country landmark', 6.8754, 81.0465);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_adams_peak', 'Adam''s Peak (Sri Pada)', 'religious_site', 'Ancient (pre-history to present)', 'Adam''s Peak, known as Sri Pada in Sinhala meaning ''Sacred Footprint,'' rises 2,243 meters and is one of the most sacred mountains in Asia. The footprint-shaped depression at its summit (1.8 meters long) is venerated by four religions: Buddhists believe it is the Buddha''s footprint, Hindus attribute it to Shiva, Muslims believe Adam rested here after expulsion from Eden, and Christians associated it with St. Thomas.', 'The summit houses a small temple containing the sacred footprint covered by a gilded roof supported by ornate pillars. Thousands of steps built into the mountainside by devotees over centuries lead to the summit. The most dramatic feature is the triangular shadow the peak casts at sunrise — a phenomenon of atmospheric optics that has awed pilgrims for millennia.', 'The pilgrimage season runs from December to May, with hundreds of thousands ascending each year. The trek, illuminated by chains of lights, takes 3–7 hours and is one of the most atmospheric religious experiences in Asia. Ibn Battuta, the 14th-century Islamic explorer, described his pilgrimage here in detail, confirming the mountain''s ancient global significance.', '["religious-temple","Heritage","Pilgrimage","Trekking","Hill Country"]', 'A-dams Peak, Sri Pa-da, Sacred Foot-print', 'Sacred to 4 religions, 2243 meters altitude, sacred footprint, pilgrimage season December to May, triangular shadow sunrise', 6.8096, 80.4994);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_horton_plains', 'Horton Plains National Park', 'national_park', 'Natural Heritage', 'Horton Plains is a UNESCO World Heritage Site and one of Asia''s most biodiverse highland ecosystems, situated at 2,100–2,300 meters in Sri Lanka''s central highlands. Named after Sir Robert Wilmot-Horton, a British governor, it is a cloud forest plateau sheltering endemic wildlife and spectacular geological formations, most famously World''s End — a sheer escarpment dropping 880 meters.', 'The plains feature rolling montane grasslands, dense cloud forests, and the dramatic Baker''s Falls waterfall. World''s End cliff provides a sheer vertical drop with views extending to the southern coast on clear days. The landscape also includes Mini World''s End and numerous streams feeding Sri Lanka''s major rivers.', 'Horton Plains forms part of the Central Highlands UNESCO World Heritage Site (2010) and is classified as one of the world''s 25 biodiversity hotspots. It shelters 24 endemic bird species, the Sri Lanka leopard, sambar deer, and hundreds of endemic plant species. The park is the source of three of Sri Lanka''s major rivers and is critical to the island''s water security.', '["urban-park","UNESCO","Wildlife","Nature","Trekking"]', 'Hor-ton Plains Na-tion-al Park, Worlds End', 'UNESCO heritage, World''s End 880 meter cliff, cloud forest, endemic wildlife, source of major rivers', 6.8018, 80.802);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_galle_fort', 'Galle Fort', 'archaeological_site', 'Portuguese (1588) / Dutch (1663)', 'Galle Fort is the best-preserved colonial fortification in Asia and a UNESCO World Heritage Site. Originally built by the Portuguese in 1588, it was massively expanded and fortified by the Dutch East India Company (VOC) beginning in 1663. The fort served as the main trading hub of the Indian Ocean for 200 years, controlling the spice and gem trade.', 'The 36-hectare fort is encircled by massive coral and granite walls up to 3 meters thick. Within its 90 bastions and 3 gates lie Dutch colonial streets laid out in a grid, featuring Dutch Reformed Church (1754), the National Museum (a converted Dutch warehouse), the Lighthouse (1938), 17th-century merchants'' townhouses, and the Groote Kerk. The architecture fuses European baroque with South Asian tropical building traditions.', 'Galle Fort remains a living city — Sri Lanka''s most intact colonial urban ensemble, housing residents, boutique hotels, restaurants, and shops alongside museums and churches. Its 2004 tsunami survival (the fort walls stopped the wave) reinforced its symbolic status as an enduring protector. It was designated a UNESCO World Heritage Site in 1988.', '["historical-monument","UNESCO","Heritage","Colonial","South Coast"]', 'Gal-le Fort', 'UNESCO World Heritage, Dutch colonial, 36 hectares, 1663, best-preserved colonial fort in Asia', 6.027, 80.217);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_mirissa', 'Mirissa Beach', 'beach', 'Contemporary', 'Mirissa is a small coastal town on Sri Lanka''s southern tip that has evolved from a quiet fishing village into one of Asia''s premier whale-watching destinations and beach resorts. The bay''s crescent shape, framed by Parrot Rock, creates a naturally sheltered swimming environment. Between November and April, blue whales — the largest animals on Earth — pass remarkably close to shore.', 'Mirissa''s beach infrastructure is characterized by casual bamboo-and-thatch restaurants and beachside boutique guesthouses rather than large resort developments, preserving the intimate village atmosphere. The iconic Parrot Rock promontory at the western end of the bay is accessible at low tide and offers panoramic views of the Indian Ocean.', 'Mirissa is Sri Lanka''s premier whale and dolphin watching destination, with blue whales, sperm whales, and spinner dolphins sighted year-round. The local fishing community that has worked these waters for generations continues to operate alongside tourism. Mirissa also serves as a hub for stilt fishing, an iconic Sri Lankan tradition of balanced fishing poles set in shallow reef waters.', '["beach","Wildlife","South Coast","Whale Watching","Swimming"]', 'Mi-ris-sa Beach', 'Blue whale watching, crescent bay, November to April season, stilt fishing, southern Sri Lanka', 5.9453, 80.4546);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_unawatuna', 'Unawatuna Beach', 'beach', 'Contemporary', 'Unawatuna is one of Sri Lanka''s most celebrated beaches, located 5 km southeast of Galle Fort. Its horseshoe-shaped bay, protected by a coral reef and headlands, creates calm turquoise waters ideal for year-round swimming. The bay was consistently rated among the world''s best beaches by travel publications through the early 2000s.', 'The bay is flanked on one end by Jungle Beach (accessible via a rocky path) and on the other by the historic Rumassala headland, which Buddhist legend holds was the hill Hanuman dropped from the Himalayas carrying medicinal herbs for Rama. The beachfront is lined with colorful restaurants and guesthouses built in a casual tropical style.', 'Rumassala, the hill above Unawatuna, is botanically exceptional — it contains plant species found nowhere else in the lowland Sri Lankan jungle, which local legend attributes to Hanuman dropping Himalayan medicinal herbs here. The area also contains two Japanese Peace Pagodas and a centuries-old temple, layering spiritual significance onto its natural beauty.', '["beach","Heritage","South Coast","Swimming","Snorkeling"]', 'U-na-wa-tu-na Beach', 'Protected horseshoe bay, coral reef, near Galle Fort, Rumassala hill, Japanese Peace Pagoda', 6.0107, 80.2494);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_weligama', 'Weligama Bay', 'beach', 'Ancient to Contemporary', 'Weligama, meaning ''sandy village,'' is a crescent-shaped bay on Sri Lanka''s south coast renowned as one of the world''s best learn-to-surf locations. The shallow, flat-breaking waves make it ideal for beginners. The bay is also famous for its stilt fishermen — men who perch on wooden crosses anchored in the shallow reef, casting lines into the sea in a technique unique to Sri Lanka.', 'The centerpiece of the bay is the small island of Taprobane, connected to shore at low tide, featuring a 1920s colonial villa built by a French count and used as a residence by various artists and writers. The stilt fishing platforms are rudimentary wooden crosses sunk into the reef, yet they represent an ingenious, centuries-old fishing technique.', 'Stilt fishing at Weligama has become one of the most photographed images of Sri Lanka. While the practice dates back centuries as a practical necessity on the coral reefs where boats could not anchor, it now forms a significant part of the cultural identity and tourist economy of the south coast. The Taprobane Island villa has hosted Paul Bowles and other notable literary figures.', '["beach","Heritage","South Coast","Surfing","Fishing"]', 'We-li-ga-ma Bay', 'Learn-to-surf bay, stilt fishermen, Taprobane Island villa, sandy village, south coast surfing hub', 5.974, 80.4292);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_tangalle', 'Tangalle', 'beach', 'Ancient to Contemporary', 'Tangalle is a charming, relatively undeveloped coastal town at the eastern end of Sri Lanka''s southern tourist circuit. Its lagoon, dramatic rock promontories, and series of wide, wild beaches attract visitors seeking a quieter alternative to busier resorts. It is one of Sri Lanka''s most important nesting sites for leatherback and loggerhead sea turtles.', 'Tangalle''s harbor is dominated by a Dutch fort built in 1774 and a distinctive Dutch Rest House perched on a coral headland with sweeping ocean views — one of the oldest government-operated rest houses in Sri Lanka. The rocky headlands separate several distinct beaches, each with different character.', 'The town''s turtle nesting beaches at Rekawa, 10 km east, attract hundreds of leatherback turtles — among the world''s largest reptiles — between April and September. The Rekawa Turtle Conservation Project is one of Sri Lanka''s oldest community-based conservation programs. Tangalle also hosts a significant fishing community maintaining traditional boat-building techniques.', '["beach","Wildlife","South Coast","Turtle Nesting","Historical"]', 'Tan-gal-le', 'Leatherback turtle nesting, Dutch fort 1774, wild undeveloped beaches, eastern south coast, Rekawa conservation', 6.0243, 80.7946);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_negombo', 'Negombo', 'attraction', 'Portuguese / Dutch Colonial', 'Negombo is a bustling coastal city 35 km north of Colombo, strategically located near Bandaranaike International Airport. One of the first ports in Sri Lanka visited by the Portuguese in the 16th century, it was a major hub for the cinnamon trade — a spice so valuable that it shaped global trade routes and colonial rivalries. Its Catholic heritage, Dutch canal system, and fish market remain defining features.', 'Negombo features a 17th-century Dutch fort (now a prison), a Dutch canal system still used for fishing boats, numerous Portuguese-influenced Catholic churches including St. Mary''s Church (1874) with its ornate interior, and a famous fish market that operates before dawn. The town has retained its heritage character despite modernization.', 'Negombo is home to one of the highest concentrations of Catholics in Sri Lanka, a legacy of Portuguese missionary activity. The town''s identity is shaped by its Karava fishing caste, known for their seafaring skills and distinct culture. The lagoon fish market, operating by lamplight from 4 AM, is one of the most atmospheric early-morning experiences in Sri Lanka.', '["historical-monument","Heritage","West Coast","Colonial","Fishing"]', 'Ne-gom-bo', 'Portuguese cinnamon port, Dutch canal system, Catholic heritage, fish market, near airport', 7.2096, 79.838);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_bentota', 'Bentota Beach', 'beach', 'Contemporary', 'Bentota is one of Sri Lanka''s premier beach resort destinations, located where the Bentota River meets the Indian Ocean on the southwest coast. It is known for its wide, golden beaches, calm lagoon ideal for water sports, and the Bentota River ecosystem with mangroves and crocodiles. Geoffrey Bawa, Sri Lanka''s most celebrated architect, designed several landmark hotels here.', 'Geoffrey Bawa''s architectural vision is most fully realized in Bentota through hotels like the Hotel Bentota Beach and Lunuganga — his country home and garden estate. Lunuganga, developed over 50 years from a 1948 rubber estate, is Sri Lanka''s most celebrated garden, blending tropical landscape with Italian renaissance garden principles and Modernist architecture.', 'Bentota''s Galapatha Raja Maha Vihara, one of Sri Lanka''s oldest temples with origins in the 12th century, stands in striking contrast to the modern resort infrastructure. The temple contains ancient murals and a legendary history connected to Queen Viharamahadevi. Bentota also serves as a hub for turtle hatching programs, river safaris, and Ayurvedic wellness tourism.', '["beach","Heritage","West Coast","Water Sports","Architecture"]', 'Ben-to-ta Beach', 'Geoffrey Bawa architecture, Lunuganga garden, river meets ocean, water sports, southwest coast resort', 6.4262, 79.9994);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_gangaramaya', 'Gangaramaya Temple', 'religious_site', 'Late 19th Century (1885)', 'Gangaramaya Temple, located beside Beira Lake in central Colombo, is one of the most important and ornate Buddhist temples in Sri Lanka. Founded in 1885 by Venerable Hikkaduwe Sri Sumangala Thero, it has grown into a vast complex that blends Buddhist, Hindu, Moorish, and Colonial architectural styles, housing an extraordinary collection of artifacts.', 'The temple''s eclectic architecture incorporates Sinhalese, Thai, Indian, and Chinese elements across its multiple buildings. The main shrine houses a magnificent seated Buddha in Thai style. The complex includes a museum containing thousands of donated objects — vintage cars, ivory tusks, crystal Buddhas, ancient coins, and rare manuscripts — creating one of Sri Lanka''s most unusual collections.', 'Gangaramaya is the spiritual anchor of Colombo and hosts the Navam Perahera — one of the largest Buddhist processions in Sri Lanka, held annually in February with over 50 elegantly decorated elephants parading around Beira Lake. The temple is also deeply involved in social welfare programs and Buddhist education, making it a center of contemporary urban Buddhist life.', '["religious-temple","Buddhist","Heritage","Colombo","Architecture"]', 'Gang-ga-ra-ma-ya Tem-ple', '1885 Buddhist temple, Beira Lake Colombo, eclectic architecture, Navam Perahera 50 elephants, art museum collection', 6.9167, 79.8571);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_independence_sq', 'Independence Square Colombo', 'monument', 'Post-Independence (1948)', 'Independence Square in Colombo''s Cinnamon Gardens district marks the site where Ceylon gained independence from British rule on February 4, 1948. The Independence Memorial Hall at its center, modeled after the ancient Kandyan audience hall (the Magul Maduwa of the Kandy Kingdom), houses a statue of Sri Lanka''s first Prime Minister D.S. Senanayake.', 'The Independence Memorial Hall is built in the traditional Kandyan architectural style — an open pavilion with a tiered roof, ornate columns, and traditional Kandyan motifs. It stands in a formal landscaped plaza with a ceremonial drive, flanked by lion statues. The broader Colombo 7 district of tree-lined boulevards and colonial-era buildings provides an elegant urban context.', 'Independence Square is the symbolic heart of Sri Lanka as a sovereign nation and the site of the annual Independence Day ceremony on February 4th. The surrounding Independence Square complex was redeveloped in 2016 into a public promenade with sports facilities, cafes, and gardens, transforming it into a vibrant urban gathering space. The area embodies both national pride and urban renewal.', '["historical-monument","Heritage","Colombo","National Symbol","Urban"]', 'In-de-pen-dence Square Co-lom-bo', 'Sri Lanka independence 1948, Kandyan architecture, D.S. Senanayake statue, national ceremony February 4th', 6.9106, 79.8617);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_lotus_tower', 'Colombo Lotus Tower', 'attraction', 'Contemporary (2019)', 'The Colombo Lotus Tower (Nelum Kuluna) is the tallest self-supported structure in South Asia, standing 356 meters tall. Completed in 2019 after 12 years of construction with Chinese assistance, it is shaped like a lotus flower — Sri Lanka''s national flower — and serves as a telecommunications tower, observation deck, hotel, and restaurant complex.', 'The tower''s distinctive lotus blossom shape features a pod of ''petals'' at the 150-meter mark housing an observation deck, revolving restaurant, and hotel floors. The structure is lit with LED lighting in changing colors each evening, making it Colombo''s most dramatic nightscape element. Its engineering integrated complex telecommunications functions with its architectural form.', 'The Lotus Tower represents Sri Lanka''s modern aspirations and Chinese-Sri Lankan diplomatic partnership. From the observation deck, visitors can see the entirety of Colombo, the coastline, and on clear days, the highlands 100 km away. It has rapidly become a symbol of modern Colombo''s urban transformation and is the most visited landmark in the capital.', '["historical-monument","Urban","Colombo","Architecture","Modern"]', 'Co-lom-bo Lo-tus Tower, Ne-lum Ku-lu-na', 'South Asia''s tallest structure, 356 meters, lotus flower design, observation deck, completed 2019', 6.9371, 79.8585);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_koneswaram', 'Koneswaram Temple Trincomalee', 'religious_site', 'Ancient (pre-2nd Century BC)', 'Koneswaram (Thirukonamalai) is one of the Pancha Ishwarams — five ancient Hindu temples of Shiva established across Sri Lanka. Perched dramatically on Swami Rock (also called Lover''s Leap) overlooking Trincomalee''s deep natural harbor, it is among the most sacred Hindu temples in Sri Lanka. The original ancient temple was largely destroyed by Portuguese colonists in 1624, who used its stones to extend Fort Frederick.', 'The current temple, rebuilt from the 20th century onwards, features classic Dravidian architecture with a towering gopuram (gateway tower) and multiple mandapas (halls). In 1950, underwater excavations in Trincomalee harbor recovered several original stone carvings and a magnificent Shiva Lingam from the ancient temple destroyed by the Portuguese — these are now housed within the complex.', 'Koneswaram is central to Tamil Hindu identity in Sri Lanka''s east and a major pilgrimage site. The Maha Shivaratri festival draws thousands of devotees. The legendary Sivan Kovil, mentioned in ancient Tamil literature like Manimekalai (5th century), was considered one of the most sacred temples in Asia before its Portuguese destruction. Its restoration represents cultural resilience.', '["religious-temple","Hindu","Heritage","East Coast","Pilgrimage"]', 'Ko-nes-wa-ram Tem-ple, Thiru-ko-na-ma-lai', 'Ancient Hindu Shiva temple, Swami Rock Trincomalee, Pancha Ishwaram, destroyed by Portuguese 1624, rebuilt, harbor views', 8.568, 81.2394);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_fort_frederick', 'Fort Frederick Trincomalee', 'archaeological_site', 'Portuguese (1623) / Dutch / British Colonial', 'Fort Frederick is a well-preserved colonial fortification built on Swami Rock promontory in Trincomalee, commanding one of the finest natural harbors in Asia — a harbor that Napoleon reportedly called ''the finest in the world.'' Originally constructed by the Portuguese in 1623 using stones from the demolished Koneswaram Hindu temple, it was subsequently occupied and expanded by the Dutch and then the British.', 'The fort features massive granite walls, bastions, a central parade ground, the former British barracks (now used by the Sri Lanka Army), and the historic Wellington House — where the young Duke of Wellington (future victor of Waterloo) briefly stayed in 1799. The Lovers'' Leap rock at the fort''s edge is associated with a tragic colonial-era legend of Dutch Governor''s daughter who leapt to her death.', 'Trincomalee harbor''s strategic importance made it a critical naval base throughout World War II. The Eastern Naval Command of the British Royal Navy was based here, and the waters outside contain numerous World War II wrecks. The fort''s Wellington connection and its commanding view of the harbor — where elephants still bathe on the beach below — make it a unique colonial heritage site.', '["historical-monument","Heritage","East Coast","Colonial","Military"]', 'Fort Fred-er-ick Trin-co-ma-lee', 'Portuguese fort 1623, Napoleon''s finest harbor, Wellington House, World War II naval base, Swami Rock promontory', 8.5683, 81.2378);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_arugam_bay', 'Arugam Bay', 'beach', 'Contemporary', 'Arugam Bay on Sri Lanka''s east coast is consistently ranked among the top 10 surf spots in the world, attracting professional surfers from May to October when the Indian Ocean swell lines up perfectly with its reef-point break. Beyond surfing, the area is surrounded by elephant safaris at Kumana National Park, ancient Muhudu Maha Viharaya temple, and lagoons teeming with crocodiles and bird life.', 'The town itself is a laid-back strip of surf shops, beachside restaurants, and guesthouses with a distinctly casual character. The ancient Muhudu Maha Viharaya, located at the northern end of the bay, is a 2,000-year-old Buddhist stupa associated with the legendary arrival of Prince Kavantissa and Princess Viharamahadevi on these shores.', 'Arugam Bay was devastated by the 2004 tsunami and its rebuild has become a story of community resilience and international support. The eastern coast''s relative isolation during decades of civil conflict preserved its natural environment, making the waters exceptionally clear and the wildlife abundant. The annual Muhudu Maha Viharaya Perahera remains an important local Buddhist cultural event.', '["beach","Surfing","East Coast","Wildlife","Adventure"]', 'A-ru-gam Bay', 'World top 10 surf spot, east coast, May to October season, 2000-year-old temple, elephant safari nearby', 6.8402, 81.8413);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_passikudah', 'Passikudah Beach', 'beach', 'Contemporary', 'Passikudah is a bay on Sri Lanka''s east coast celebrated for having one of the most extraordinary beach environments in Asia: a natural sandbar creates a vast, extremely shallow lagoon extending hundreds of meters from shore, where the depth rarely exceeds waist height. The calm, crystal-clear turquoise water makes it one of the safest and most beautiful swimming beaches in South Asia.', 'The bay''s defining feature is entirely natural — an arc of white sand beach curving around the shallow lagoon, protected from ocean swells by a natural reef. The government developed Passikudah as a high-end resort zone after the end of the civil conflict in 2009, attracting international hotel chains. The absence of development through the conflict years left the water and reef in pristine condition.', 'Passikudah''s opening to tourism post-2009 became a symbol of Sri Lanka''s national reconciliation and the reopening of the north and east to visitors after decades of restricted access. The bay is now a centerpiece of eastern Sri Lanka''s economic development strategy. Its coral reef systems, largely undamaged by human activity during the conflict years, are now among the best-preserved in Sri Lanka.', '["beach","East Coast","Swimming","Luxury","Snorkeling"]', 'Pas-si-ku-dah Beach', 'Shallowest bay in Asia, crystal turquoise lagoon, east coast, pristine reef, post-war development symbol', 7.9282, 81.5611);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_batticaloa', 'Batticaloa Lagoon', 'attraction', 'Ancient to Contemporary', 'Batticaloa, known as ''Batti,'' is a historic eastern city set on a lagoon island connected to the mainland by causeways. It is famous for the ''Singing Fish'' phenomenon — a musical sound emanating from the depths of Batticaloa Lagoon at night during certain seasons, attributed by locals to fish or shells. The city''s Dutch Fort (1628) and its role in Tamil cultural heritage make it a significant east coast destination.', 'The Batticaloa Dutch Fort, built in 1628, is one of the largest fortifications built by the Dutch in Sri Lanka. Its star-shaped plan and coral-stone walls have survived remarkably well. The city''s urban character reflects its Tamil cultural identity, with numerous Kovils (Hindu temples) and the Kallady Bridge connecting the lagoon island to the mainland.', 'The Singing Fish of Batticaloa Lagoon has fascinated scientists, sailors, and travelers for centuries. Samuel Baker (the Victorian explorer) described it in 1855; it is believed to be produced by fish or mollusks vibrating their bodies. The lagoon also holds important cultural events including the multi-day Thai Pongal harvest festival and the annual Madu Shrine boat procession.', '["historical-monument","Heritage","East Coast","Lagoon","Mystery"]', 'Bat-ti-ca-lo-a La-goon', 'Singing fish lagoon, Dutch fort 1628, Tamil cultural hub, island city, east coast heritage', 7.7171, 81.6924);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_nallur_kovil', 'Nallur Kandaswamy Kovil', 'religious_site', '10th Century (original) / 17th Century (current)', 'Nallur Kandaswamy Kovil is the most important Hindu temple in northern Sri Lanka and one of the most sacred in Asia, dedicated to Lord Murugan (Skanda). The original temple dates to the 10th century Jaffna Kingdom era. It was repeatedly destroyed and rebuilt — most famously demolished by the Portuguese in 1620 and rebuilt in its current form under the Dutch period. Today it is the spiritual heart of Jaffna''s Tamil Hindu community.', 'The temple complex is dominated by a soaring 12-tiered Dravidian-style gopuram (gateway tower) richly decorated with hundreds of painted stucco figures of deities. The main shrine, festival hall (mandapam), tank, and subsidiary shrines are enclosed within a walled compound. A golden flagstaff (kodimaram) at the entrance traditionally marks its religious authority over the region.', 'The Nallur Festival, held over 25 days in July–August, is the largest and most elaborate Hindu festival in Sri Lanka, with chariot processions, fire-walking, hook-swinging (kavadi), and massive daily attendances of over 500,000 devotees during its climax. The festival survived even through the decades of civil conflict, maintaining its role as the anchor of Tamil cultural and religious identity in the north.', '["religious-temple","Hindu","Heritage","North Sri Lanka","Pilgrimage"]', 'Nal-lur Kan-da-swa-my Ko-vil', 'Most sacred Hindu temple north Sri Lanka, Lord Murugan, 25-day festival 500,000 devotees, 12-tiered gopuram, Jaffna', 9.6677, 80.0276);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_jaffna_fort', 'Jaffna Fort', 'archaeological_site', 'Portuguese (1618) / Dutch (1658)', 'Jaffna Fort is the largest colonial-era fort in Sri Lanka and one of the most impressive in Asia, built by the Portuguese in 1618 and dramatically expanded by the Dutch after 1658. It served as the seat of colonial power in northern Sri Lanka for 300 years. The fort changed hands multiple times between Portuguese, Dutch, British, and — remarkably — during Sri Lanka''s civil conflict was held by both government forces and the LTTE at different periods.', 'The fort covers 55 acres with a five-pointed star plan featuring massive pentagonal bastions, a wide moat (still water-filled), drawbridge approach, and walls up to 3.5 meters thick. Within the walls stand the former Dutch church (now a museum), colonial administrative buildings, and the ruins of the Portuguese Captain''s house. A lighthouse stands within the fort compound.', 'Jaffna Fort represents a layered history of Jaffna city''s colonial past and recent civil conflict. Having been severely damaged during the civil war (1983–2009), its restoration is a symbol of post-war reconciliation and the reconnection of northern Sri Lanka with the national heritage network. The fort now houses a museum documenting Dutch colonial history in northern Ceylon.', '["historical-monument","Heritage","North Sri Lanka","Colonial","Archaeological"]', 'Jaf-fna Fort', 'Portuguese fort 1618, Dutch expanded, 55 acres, star plan, post-war reconciliation symbol, Jaffna city', 9.6596, 79.9992);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_yala', 'Yala National Park', 'national_park', 'Established 1938', 'Yala National Park is Sri Lanka''s most famous wildlife reserve and the second-largest national park in the country, covering 979 square kilometers. It has the highest density of leopards in the world — an estimated 30–35 leopards per 100 square kilometers — making it the premier destination globally for leopard sightings. Yala also holds the ruins of several ancient Buddhist sites within its boundaries, revealing that the area was once densely populated.', 'Within Yala''s boundaries lie the ruins of Sithulpawwa — a 2,000-year-old rock monastery that once housed 12,000 monks, now partly restored. The Magul Maha Viharaya stupa, dating to the 2nd century BC, and the Akasa Chaitya are other significant archaeological sites within the park, creating a unique environment where wildlife and ancient ruins coexist.', 'Yala''s coastal section was devastated by the 2004 tsunami — one of the largest wildlife losses in Sri Lanka''s history — but the park''s resilience became an international story of ecological recovery. Block 1 (Ruhuna National Park) is the most visited section, while Blocks 2 through 5 offer increasingly remote wilderness experiences. Elephants, sloth bears, crocodiles, peacocks, and hundreds of bird species share the landscape.', '["urban-park","Wildlife","Leopard","Safari","South Coast"]', 'Ya-la Na-tion-al Park', 'Highest leopard density in world, 979 square kilometers, elephants, ancient ruins, 2004 tsunami survivor', 6.3723, 81.5212);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_udawalawe', 'Udawalawe National Park', 'national_park', 'Established 1972', 'Udawalawe National Park was established in 1972 to protect the catchment of the Udawalawe Reservoir, one of Sri Lanka''s major irrigation projects. It has grown into the best destination in Asia for reliable, close-range elephant sightings — with a resident population of 500–700 elephants. The park''s open, semi-arid scrub landscape allows exceptional wildlife visibility.', 'The park''s defining landscape feature is the 3,800-hectare Udawalawe Reservoir (Walawe Ganga Reservoir) completed in 1968, around which the grasslands and scrub forests support extraordinary wildlife concentrations. The Elephant Transit Home, operated by the Wildlife Conservation Department, rehabilitates orphaned elephant calves before returning them to the wild.', 'Udawalawe is considered Africa-style safari territory in Asia — open plains, large elephant herds, and reliable big mammal sightings make it uniquely different from Sri Lanka''s dense-forest parks. The Elephant Transit Home is one of the world''s most successful elephant orphan rehabilitation programs and gives visitors an extraordinary opportunity to observe young elephants being fed and cared for.', '["urban-park","Wildlife","Elephant","Safari","South Sri Lanka"]', 'U-da-wa-la-we Na-tion-al Park', 'Best Asian elephant safari, 700 elephants, rehabilitation center, open plains, Walawe Reservoir', 6.4742, 80.8993);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_wilpattu', 'Wilpattu National Park', 'national_park', 'Established 1938', 'Wilpattu National Park is Sri Lanka''s largest national park, covering 1,317 square kilometers of northwestern Sri Lanka. Its name means ''Land of Lakes'' in Sinhalese, referring to its unique feature: over 60 naturally formed lakes called ''villus'' — seasonal rain-fed depressions that attract extraordinary concentrations of wildlife. The park was closed for 20 years during the civil war and reopened in 2010.', 'Wilpattu''s landscape is dominated by its characteristic villus — circular lakes ringed by sandy beaches that provide perfect wildlife observation points. The park''s central region is dense dry scrub jungle transitioning to open parkland around the lakes. Ancient ruins of the Kala Wewa irrigation system and Panaikkadanthurai ruins are found within the park.', 'Wilpattu''s 20-year closure during the civil conflict allowed its ecosystem to recover exceptionally, making it today perhaps the most pristine large national park in Sri Lanka. Its leopard population, undisturbed for decades, is believed to be one of the densest in the country. The park also holds the legendary Kudiramalai Point, traditionally identified as the landing spot of Prince Vijaya — the founding ancestor of the Sinhalese people — in 543 BC.', '["urban-park","Wildlife","Leopard","Nature","North West"]', 'Wil-pat-tu Na-tion-al Park, Land of Lakes', 'Sri Lanka''s largest park, 60 natural lakes, Land of Lakes, 20-year closure, pristine leopard habitat', 8.456, 79.9283);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_bundala', 'Bundala National Park', 'national_park', 'Established 1993', 'Bundala National Park is a wetland sanctuary on Sri Lanka''s southeastern coast, designated a Ramsar Wetland of International Importance and a UNESCO Biosphere Reserve. Its chain of five lagoons forms a critical wintering and staging ground for migratory shorebirds from the Palearctic region, with over 200 bird species recorded including large flocks of greater flamingos from India.', 'Bundala''s landscape is a mosaic of saline lagoons, coastal dunes, and dry scrub jungle covering 62 square kilometers. The lagoons create a complex intertidal ecosystem supporting breeding waterbirds, crocodiles, sea turtles (nesting on beaches), and a resident herd of elephants. The park''s boundary extends to the Indian Ocean coast.', 'Bundala serves a critical ecological role as one of South Asia''s most important wintering grounds for migratory birds, with over 150,000 waterbirds using the lagoons annually. The greater flamingo flocks from the Rann of Kutch in India are among the most dramatic seasonal wildlife spectacles in Sri Lanka. The park is a centerpiece of sustainable eco-tourism development in Sri Lanka''s southeast.', '["urban-park","Wildlife","Birdwatching","South Coast","UNESCO"]', 'Bun-da-la Na-tion-al Park', 'Ramsar wetland, UNESCO biosphere, flamingos, 200 bird species, coastal lagoon system, southeastern Sri Lanka', 6.1988, 81.1631);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_hikkaduwa', 'Hikkaduwa Coral Reef', 'beach', 'Natural Heritage', 'Hikkaduwa is Sri Lanka''s original beach resort destination, famous for its shallow coral sanctuary that shelters enormous sea turtles, colourful reef fish, and vibrant hard corals within swimming distance of shore. Declared a National Marine Sanctuary in 1979, the reef extends 300 metres offshore and remains one of the most accessible coral reef ecosystems in South Asia.', 'The reef is entirely natural, comprising plate corals, brain corals, and staghorn formations in depths of 2–5 metres. The sandy beach is backed by a colourful strip of guesthouses, surf shops, and restaurants. The town retains much of its 1970s bohemian backpacker character despite decades of tourism development.', 'Hikkaduwa became internationally famous in the early 1970s as one of the first stops on the Asia hippie trail, attracting travellers from around the world. The resident sea turtle population — green turtles, hawksbill, and leatherback — have learned to approach snorkellers, creating one of the most memorable wildlife encounters on the island. The 2004 tsunami caused extensive reef damage that has since partially recovered.', '["beach","Wildlife","Snorkeling","South Coast","Marine"]', 'Hik-ka-du-wa Cor-al Reef', 'National marine sanctuary, resident sea turtles, 1970s surf town, shallow reef, south west coast', 6.139, 80.103);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_matara_fort', 'Matara Star Fort', 'archaeological_site', 'Dutch Colonial (1763)', 'The Matara Star Fort is a compact and beautifully preserved Dutch fortification built in 1763 across the Nilwala River from the main Matara Fort. Its distinctive five-pointed star plan allowed cannon coverage in every direction with no blind spots — a masterpiece of 18th-century military geometry. It is one of the smallest but most perfectly intact Dutch forts in Asia.', 'The star-shaped design features five triangular bastions projecting from a central hexagonal core, constructed from coral stone and brick with lime mortar. The walls stand 4–5 metres high and are surrounded by a water-filled moat. A single arched gateway with the Dutch East India Company (VOC) crest is the only entrance. Inside, the original guardhouse still stands.', 'The Star Fort was built to protect the nearby Matara Fort from landward attack across the river. Today it houses a small museum displaying Dutch-era artefacts including cannon balls, coins, and maps. Together with the main Matara Fort ramparts and the 18th-century Dutch Reformed Church nearby, it forms one of the best-preserved clusters of Dutch colonial military architecture in Sri Lanka.', '["historical-monument","Heritage","Colonial","South Coast","Archaeological"]', 'Ma-ta-ra Star Fort', 'Dutch star fort 1763, five-pointed bastions, VOC crest gateway, moat, perfectly preserved colonial military gem', 5.9476, 80.5455);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_pinnawala', 'Pinnawala Elephant Orphanage', 'attraction', 'Established 1975', 'Pinnawala Elephant Orphanage, established in 1975 by the Sri Lanka Department of Wildlife Conservation, is the world''s largest captive elephant herd and one of Asia''s most celebrated wildlife attractions. Originally set up to care for orphaned baby elephants found in the wild, the colony has grown to over 90 elephants living together on a 25-acre coconut plantation beside the Maha Oya River.', 'The facility comprises open fields, sheltered stalls, and direct river access to the Maha Oya, where the entire herd is bathed twice daily — one of the most spectacular wildlife spectacles in Asia. The surrounding village of Pinnawala has grown around the orphanage, with viewing platforms and riverside cafes offering close-up views of bathing elephants.', 'Pinnawala''s twice-daily elephant bath in the Maha Oya river, with dozens of elephants of all ages wading and splashing, is among the most photographed wildlife events in Sri Lanka. The orphanage has successfully bred elephants in captivity and returned some to the wild. Its location between Colombo and Kandy makes it one of the most visited attractions on the island.', '["urban-park","Wildlife","Elephant","Conservation","Family"]', 'Pin-na-wa-la El-e-phant Or-phan-age', 'World''s largest captive elephant herd, 90 elephants, river bathing twice daily, 1975, between Colombo and Kandy', 7.2955, 80.3518);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_knuckles', 'Knuckles Mountain Range', 'national_park', 'Natural Heritage', 'The Knuckles Mountain Range, named for its resemblance to a clenched fist when viewed from the Kandy plains, is a UNESCO World Heritage Site comprising five major peaks and a complex of 34 summits in central Sri Lanka. The range is one of the island''s most biodiverse areas, sheltering endemic species found nowhere else on Earth and hosting some of the finest trekking terrain in Asia.', 'The range spans 155 square kilometres of misty cloud forest, montane grasslands, and deep river gorges. Traditional villages practising ancient Kandyan farming methods — including chena (slash-and-burn) cultivation and terraced paddy — are scattered through the lower valleys. The Corbett''s Gap viewpoint provides panoramic views across Kandy and the central highlands.', 'The Knuckles Range forms part of the Central Highlands UNESCO World Heritage Site (2010) and contains 34 endemic vertebrate species. Ancient footpaths connecting isolated mountain villages have been converted into trekking trails of 2–5 days. The area''s traditional communities maintain folk medicinal plant knowledge passed down for generations, making it a living laboratory of ethnobotany.', '["urban-park","UNESCO","Trekking","Wildlife","Hill Country"]', 'Knuck-les Moun-tain Range', 'UNESCO heritage, clenched fist silhouette, 34 peaks, endemic species, multi-day trekking, central highlands', 7.4635, 80.7995);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_ravana_falls', 'Ravana Falls', 'attraction', 'Natural Heritage / Ancient Legend', 'Ravana Falls is one of the widest waterfalls in Sri Lanka, plunging 25 metres from the cliff edge above the Ella–Wellawaya road. The falls are deeply embedded in Sri Lankan mythology, said to be the site where the demon king Ravana hid Sita after abducting her from Rama — the cave behind the curtain of water is known as Ravana''s Cave in local legend.', 'The falls cascade over a broad basalt cliff face, spreading into a wide curtain of white water that narrows during dry season. The cliff face is lush with ferns and mosses, and the plunge pool at the base is accessible for swimming. The cave mouth is visible through the falling water and is accessible via a steep trail, though it is shallow and of limited depth.', 'Ravana Falls sits at the heart of the Ramayana trail in Sri Lanka, a pilgrim circuit linking sites associated with the Hindu epic Ramayana that draws thousands of Indian Hindu tourists annually. Sri Lankan tradition holds that Ravana, the demon king, was also a learned king of great power who ruled the island before the events of the Ramayana, making him a complex and fascinating figure in local heritage.', '["urban-park","Nature","Waterfall","Hill Country","Mythology"]', 'Ra-va-na Falls El-la', '25-metre wide waterfall, Ravana''s cave legend, Ramayana trail, Ella area, Hindu pilgrimage site', 6.8656, 81.0467);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_bambarakanda', 'Bambarakanda Falls', 'attraction', 'Natural Heritage', 'Bambarakanda Falls is the highest waterfall in Sri Lanka, plunging 263 metres in a single free-falling drop from the Horton Plains escarpment into the valley below. Located in the Badulu Oya river basin near Haputale in the southern highlands, it is one of the most dramatic natural features in the country, visible from several kilometres away.', 'The falls drop from a sheer cliff in a near-vertical single cascade, creating a fine mist that nourishes the lush montane vegetation surrounding the pool. The approach involves a 45-minute walk through pine forest and tea estates. The viewing area provides an unobstructed view of the full height of the falls against the surrounding highland escarpment.', 'Bambarakanda''s dramatic height and remote highland setting make it a popular destination for hikers and nature lovers who rarely visit this less-touristed part of Sri Lanka. The surrounding area, near Haputale, is famous for its tea estates and the dramatic Lipton''s Seat viewpoint, creating a highland trekking circuit of considerable scenic beauty.', '["urban-park","Nature","Waterfall","Trekking","Hill Country"]', 'Bam-ba-ra-kan-da Falls', 'Highest waterfall in Sri Lanka, 263 metres, single free-fall, Horton Plains escarpment, Haputale highlands', 6.7544, 80.7879);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_aukana', 'Aukana Buddha Statue', 'archaeological_site', '5th Century AD', 'The Aukana Buddha is a magnificent 12-metre standing Buddha statue carved from a single solid granite boulder in the 5th century AD, commissioned by King Dhatusena — the same king who built the legendary Kalawewa tank. Considered the finest rock-cut Buddha statue in Sri Lanka and one of the greatest examples of ancient South Asian sculpture, the statue still stands in near-perfect condition after 1,500 years.', 'The statue stands in the abhaya mudra (hand raised in blessing) pose, carved from a single granite outcrop with only the lotus pedestal separately constructed. Its proportions follow ancient Sinhalese canonical sculpture rules precisely. The face retains extraordinary detail — serene features, elongated earlobes, and the ushnisha (cranial protuberance) marking enlightenment. The water flowing from a vessel in the right hand is a unique artistic feature.', 'Aukana is one of the four great standing Buddha statues of Sri Lanka, alongside Maligawila, Buduruvagala, and Sasseruwa. It remains an active site of Buddhist veneration, with monks maintaining a small temple complex around the statue. The site is most atmospheric at sunrise, when early morning pilgrims arrive and the golden light illuminates the towering stone figure.', '["historical-monument","Buddhist","Heritage","Archaeological","Sculpture"]', 'Au-ka-na Bud-dha Sta-tue', '12-metre standing Buddha, carved from single granite boulder, 5th century AD, King Dhatusena, finest rock sculpture in Sri Lanka', 8.2003, 80.5766);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_medirigiriya', 'Medirigiriya Vatadage', 'archaeological_site', '7th Century AD', 'The Medirigiriya Vatadage is one of the best-preserved circular relic houses (vatadage) in Sri Lanka, dating to the 7th century AD. Located on a rocky plateau in the Polonnaruwa district, it is remarkably intact — retaining its concentric stone pillars, moonstone entrance steps, and four seated Buddha statues at the cardinal points, all carved from white limestone.', 'The vatadage structure comprises three concentric circles of stone pillars — the outer ring has 32 pillars, the middle ring 16, and the inner ring 8 — supporting what was once a conical timber-and-tile roof over the central stupa. Four finely carved seated Buddhas face the four directions. The intricately carved moonstone steps at the entrance are considered among the finest in Sri Lanka.', 'Medirigiriya is significant as one of Sri Lanka''s lesser-visited but best-preserved ancient sites, offering an experience of authentic archaeological heritage without crowds. The surrounding Medirigiriya forest reserve shelters a population of wild elephants, adding a wildlife dimension to the cultural visit. The site is included in the UNESCO Polonnaruwa World Heritage Zone.', '["historical-monument","UNESCO","Archaeological","Buddhist","Heritage"]', 'Me-di-ri-gi-ri-ya Va-ta-da-ge', '7th century circular relic house, concentric stone pillars, four Buddha statues, finest moonstone steps, Polonnaruwa zone', 8.0003, 81.0218);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_national_museum_colombo', 'National Museum of Colombo', 'museum', 'Established 1877', 'The National Museum of Colombo is the largest museum in Sri Lanka, founded in 1877 during British colonial rule by Governor Sir William Henry Gregory. Its collection spans over 100,000 artefacts tracing Sri Lankan civilization from prehistoric times through the colonial era, including the crown jewels and throne of the last Kandyan king — Sri Vikrama Rajasinha — surrendered to the British in 1815.', 'The museum occupies a grand two-storey Italian Renaissance-style building with a porticoed facade, set within Viharamahadevi Park in Colombo 7. Its white colonnaded exterior and high-ceilinged galleries were designed to impress colonial visitors. Inside, rooms are arranged thematically — prehistoric, ancient, medieval, and colonial — with a natural history wing displaying endemic Sri Lankan fauna.', 'The museum''s centrepiece is the Kandyan royal regalia — crown, sword, and throne — surrendered at the 1815 Kandyan Convention that ended Sri Lanka''s independence. This collection represents the last tangible links to 2,000 years of Sinhalese royal history. The museum also houses the remarkable Sigiriya fresco reproductions, ancient manuscripts, and the largest collection of colonial-era paintings in South Asia.', '["museum","Heritage","Colombo","Colonial","History"]', 'Na-tion-al Mu-se-um of Co-lom-bo', 'Founded 1877, Kandyan royal crown and throne, 100,000 artefacts, Italian Renaissance building, Sri Lanka''s largest museum', 6.9108, 79.8613);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_pigeon_island', 'Pigeon Island National Park', 'national_park', 'Natural Heritage', 'Pigeon Island National Park, located just 1 km offshore from Nilaveli beach north of Trincomalee, is the only coral reef national park in Sri Lanka. Its shallow clear waters shelter the healthiest coral reef ecosystem on the island, with visibility up to 30 metres. Rock pigeons nesting on the island gave it its name. Blacktip reef sharks and spinner dolphins are regular visitors.', 'The park comprises two small rocky islands surrounded by pristine coral reefs in the shallow waters of the Bay of Bengal. The larger island has a small sandy beach where visitors can land by boat. The reef ecosystem comprises extensive staghorn and plate coral gardens in 2–10 metres of water, home to over 300 species of fish and several species of sea turtle.', 'Pigeon Island represents one of Sri Lanka''s most significant marine conservation efforts and a model for balancing eco-tourism with reef protection. Access is strictly regulated by boat permits and no-anchor zones protect the fragile coral. The park was declared a National Park in 2003, recognising the reef as a nationally irreplaceable natural asset along the less-visited east coast.', '["urban-park","Wildlife","Snorkeling","Diving","East Coast"]', 'Pi-geon Is-land Na-tion-al Park', 'Only coral reef national park in Sri Lanka, 30-metre visibility, blacktip sharks, 300 fish species, Trincomalee coast', 8.5975, 81.2246);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_nilaveli', 'Nilaveli Beach', 'beach', 'Contemporary', 'Nilaveli is a long, wide, white-sand beach stretching 8 km north of Trincomalee on Sri Lanka''s northeast coast. Protected from the southwest monsoon by the geography of the Bay of Bengal, it offers calm swimming conditions from April to September when the west coast is rough. It serves as the mainland base for boat trips to Pigeon Island National Park.', 'Nilaveli''s beach is characterised by its extraordinary width at low tide — sometimes 100 metres from wave line to vegetation — backed by a fringe of casuarina and palm trees. The beachfront development is low-key compared to the south coast, with small guesthouses and mid-range hotels. Fishing villages at either end of the beach maintain traditional boat-building and net-fishing practices.', 'Nilaveli was severely affected by both the 2004 tsunami and decades of civil conflict that restricted access to the north and east. Its post-war development as a tourist destination represents an important dimension of Sri Lanka''s national reconciliation process. The beach''s remarkable cleanliness and low visitor numbers, a legacy of its isolation, make it one of the most pristine long beaches in South Asia.', '["beach","East Coast","Swimming","Nature","Peaceful"]', 'Ni-la-ve-li Beach', '8 km pristine white sand, calm April to September, Pigeon Island base, post-war east coast, Trincomalee north', 8.6388, 81.2281);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_sinharaja', 'Sinharaja Rain Forest', 'national_park', 'Natural Heritage', 'Sinharaja is Sri Lanka''s last viable area of primary lowland tropical rainforest and a UNESCO World Heritage Site, designated in 1988. Meaning ''Lion King'' in Sinhalese, it shelters an extraordinary concentration of endemic species — over 60% of Sri Lanka''s endemic woody plant species grow here, along with 50% of endemic birds, 22 endemic reptiles, and 19 endemic amphibians.', 'The forest is a multi-layered tropical ecosystem with a continuous canopy at 40–45 metres, an understorey of tree ferns and palms, and a complex floor stratum of epiphytes, mosses, and fungi. Several rivers originate in Sinharaja, including the Gin Ganga. Traditional walking trails wind through the forest interior with local guides identifying endemic species.', 'Sinharaja is one of Asia''s most important biodiversity hotspots and is considered Sri Lanka''s most ecologically sensitive protected area. The forest''s remarkably high endemism rate is explained by Sri Lanka''s ancient geological separation from India — species evolved independently for millions of years. Mixed flocking bird tours at dawn, led by expert local guides, attract ornithologists worldwide.', '["urban-park","UNESCO","Wildlife","Rainforest","Endemic Species"]', 'Sin-ha-ra-ja Rain For-est, Lion King Forest', 'UNESCO rainforest, Sri Lanka''s last primary lowland jungle, 60% endemic plants, 50% endemic birds, extraordinary biodiversity', 6.3983, 80.4333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_kitulgala', 'Kitulgala White Water Rafting', 'attraction', 'Contemporary / British Colonial', 'Kitulgala is a small town on the Kelani River in Sri Lanka''s wet zone, famous as the premier white water rafting destination in the country and as the filming location for David Lean''s 1957 Oscar-winning film ''The Bridge on the River Kwai.'' The Kelani River''s rapids — graded 2–4 — provide an exhilarating 2-hour rafting experience through dense rainforest.', 'The town is set in deep river valley jungle, and the Kelani River''s rapids are created by the geological formations of the river bed as it descends from the central highlands. The original bridge built for the film has long been removed, but the surrounding jungle landscape remains essentially unchanged from its cinematic appearance. Birdwatching platforms and jungle camps have been established for eco-tourists.', 'Kitulgala''s cinematic heritage adds a unique cultural dimension to its natural adventure offerings. The town is also a significant birdwatching destination — it lies within the wet zone lowland rainforest, one of Sri Lanka''s richest bird habitats, and is one of the best places to see the Sri Lanka Blue Magpie and other endemic rainforest birds. The Kelani River is also sacred, used for ceremonial bathing by Hindu communities upstream.', '["urban-park","Adventure","Nature","River","Rainforest"]', 'Ki-tul-ga-la White Wa-ter Raft-ing', 'Premier Sri Lanka rafting, Bridge on the River Kwai filming location, Kelani River rapids, endemic birdwatching, wet zone jungle', 6.9897, 80.4167);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_mannar_fort', 'Mannar Fort', 'archaeological_site', 'Portuguese (1560) / Dutch Colonial', 'Mannar Fort is one of the oldest colonial fortifications in Sri Lanka, originally constructed by the Portuguese in 1560 on a strategic peninsula controlling the northern sea route to India. It was subsequently captured and expanded by the Dutch in 1658. Mannar Island, connected to the mainland by a causeway, was for centuries the main crossing point for traders, pilgrims, and armies between India and Sri Lanka.', 'The fort occupies the tip of Mannar Island with sea on three sides. Its rectangular plan features four corner bastions, a moat, and an arched main gate bearing the Dutch East India Company insignia. Within the walls stand the ruins of a colonial church, a well, and former barracks. The fort is unusually well-preserved given its remote location and relative obscurity.', 'Mannar Island lies at the northern end of Adam''s Bridge — the legendary causeway of stone shoals stretching 18 km towards Rameswaram in India, said in the Ramayana to have been built by Hanuman''s army to rescue Sita. The island is a major staging point for migratory birds and hosts Sri Lanka''s largest population of wild donkeys — descendants of animals brought by Portuguese colonists.', '["historical-monument","Heritage","Colonial","North Sri Lanka","Archaeological"]', 'Man-nar Fort', 'Portuguese fort 1560, Dutch colonial, Adam''s Bridge nearby, wild donkeys, northern sea route, Mannar Island', 8.9781, 79.9048);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_adams_bridge', 'Adam''s Bridge (Rama''s Bridge)', 'attraction', 'Ancient / Natural Formation', 'Adam''s Bridge, known in Hindu tradition as Rama Setu (Rama''s Bridge), is a chain of natural limestone shoals stretching 48 km between Mannar Island in Sri Lanka and Rameswaram Island in India. These shallow shoals — mostly 1–10 metres deep — form a near-continuous natural bridge across the Palk Strait. The formation is central to the Hindu epic Ramayana and is a major pilgrimage site.', 'The bridge is a geological formation of calcium carbonate shoals and sand banks, ancient coral reefs, and limestone ridges. NASA satellite imagery has revealed the striking linearity of the formation, fuelling debate about its natural versus constructed origins. The chain of islands and shoals is called Dhanushkodi on the Indian side, where the ancient pilgrimage town was devastated by a cyclone in 1964.', 'In the Ramayana, Hanuman''s army of Vanaras built this bridge in 5 days to enable Rama''s crossing to Lanka to rescue Sita from Ravana. Hindu tradition regards it as a sacred site, and millions of Indian pilgrims visit Rameswaram partly to connect with this legend. Sri Lanka''s government has consistently rejected proposals to dredge a shipping channel through the shoals, in part due to their religious significance.', '["historical-monument","Mythology","Heritage","Pilgrimage","North Sri Lanka"]', 'A-dams Bridge, Ra-ma Se-tu, Ra-mas Bridge', '48 km chain of limestone shoals to India, Ramayana Hanuman''s bridge, Hindu pilgrimage, NASA visible from space', 9.0847, 79.6699);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_lipton_seat', 'Lipton''s Seat', 'attraction', 'British Colonial', 'Lipton''s Seat is a dramatic viewpoint at 1,970 metres altitude in the Haputale mountains of southern Sri Lanka''s hill country, named after Sir Thomas Lipton — the Scottish tea merchant and Lipton Tea founder who surveyed his vast Dambatenne tea estate from this clifftop point. On clear mornings the view extends across a sea of tea-covered hillsides to the southern coast and sometimes to the Maldives.', 'The viewpoint is a simple rocky promontory at the end of a winding estate road through the Dambatenne tea estate. The Dambatenne Tea Factory at the base of the hill was built in 1890 by Thomas Lipton himself and remains operational, offering tours. The hillsides visible from the seat are covered in the geometric patterns of tea bushes trimmed to waist height, one of the most distinctive landscapes in Asia.', 'Sir Thomas Lipton transformed the global tea industry in the 19th century, buying directly from growers and selling directly to consumers, bypassing merchant middlemen. His Haputale estates were central to his business empire. Today Lipton''s Seat is one of Sri Lanka''s most dramatic sunrise viewpoints — the trek up through tea estates in the early morning mist, ending with panoramic views, is an iconic Sri Lankan highland experience.', '["historical-monument","Heritage","Tea Country","Hill Country","Viewpoint"]', 'Lip-tons Seat, Dam-ba-ten-ne Tea Es-tate', 'Thomas Lipton viewpoint, 1970 metres, Dambatenne tea estate, views to southern coast, sunrise tea country panorama', 6.7849, 80.8714);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_kumana', 'Kumana National Park', 'national_park', 'Established 1938', 'Kumana National Park (formerly Yala East) is a remote coastal wildlife sanctuary on Sri Lanka''s far south-eastern corner, bordering the Kumana Villu — a large coastal lagoon system that hosts one of the largest waterbird breeding colonies in Asia. Over 200 bird species including painted storks, pelicans, and open-billed storks nest here in their thousands each May–July.', 'The park''s defining feature is the Kumana Villu, a vast estuarine wetland where mangrove channels meet coastal lagoons, creating a nesting habitat of extraordinary density. The park also protects dry forest, scrubland, and beach habitats supporting leopards, elephants, sloth bears, and crocodiles. Ancient ruins at Magul Maha Viharaya within the park reveal 2,000-year-old human presence.', 'Kumana''s remoteness — reached only by 4WD vehicle through the eastern lowlands — has preserved it as one of the least-disturbed national parks in Sri Lanka. The waterbird breeding colony at Kumana Villu is considered one of the greatest ornithological spectacles in South Asia. The ancient Magul Maha Viharaya ruins, associated with the legendary romance of Prince Kavantissa and Princess Viharamahadevi, add a mythological dimension.', '["urban-park","Wildlife","Birdwatching","East Coast","Nature"]', 'Ku-ma-na Na-tion-al Park', 'Asia''s largest waterbird colony, painted storks and pelicans, remote southeastern park, leopards and elephants, ancient ruins', 6.5667, 81.7167);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_ritigala', 'Ritigala Ancient Ruins', 'archaeological_site', '2nd Century BC', 'Ritigala is a remote forest monastery complex on a rocky mountain massif rising from the Dry Zone plains north of Anuradhapura. Founded as early as the 2nd century BC, it was a home for the Pamsukulika monks — an ascetic forest-dwelling sect who rejected luxury and lived in absolute simplicity. The ruins are unique in Sri Lanka — no stupas or Buddha images, only meditation walkways and monastic platforms.', 'The ruins comprise a series of double-platform structures (parivenas) connected by raised stone walkways (pathways of paved stone), all carved with exceptional precision from locally quarried rock. The structures represent the living quarters and meditation halls of the ascetic monks. The site is notable for what is absent — the ornate stupas and Buddha statues of mainstream Buddhism — reflecting the strict Pamsukulika ideology.', 'Ritigala is considered one of the most atmospheric and mysterious ancient sites in Sri Lanka. Its forest setting — the mountain is a protected strict natural reserve sheltering endemic plants — means the ruins are deeply embedded in jungle, with roots and trees gradually reclaiming the stonework. The silence and remoteness create an experience of genuine discovery. The site appears in ancient chronicles as a meeting place of legendary monks.', '["historical-monument","Archaeological","Heritage","Buddhist","Hidden Gem"]', 'Ri-ti-ga-la An-cient Ru-ins', '2nd century BC forest monastery, ascetic Pamsukulika monks, no Buddha statues, mysterious stone walkways, jungle-engulfed ruins', 8.1432, 80.7053);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_buduruvagala', 'Buduruvagala Rock Temple', 'archaeological_site', '8th–9th Century AD', 'Buduruvagala is a group of seven colossal rock-carved figures set into a jungle cliff face near Wellawaya, dating to the Mahayana Buddhist period of the 8th–9th centuries AD. The central figure is a 15-metre standing Buddha — the largest rock-cut Buddha in Sri Lanka — flanked by Bodhisattva Maitreya, the multi-armed Tara, and rare Vajrayana tantric figures that hint at a brief but extraordinary Mahayana phase in Sri Lankan Buddhism.', 'The sculptures are carved directly into a granite rock face in bas-relief, with the standing Buddha still retaining traces of its original orange stucco paint coating. The Bodhisattva to the right holds a flame-shaped object unique in Sri Lankan art. A rare depiction of Tara — the female Bodhisattva — stands in triple-flexion pose (tribhanga), displaying the Mahayana artistic canon not typically found in Theravada Sri Lanka.', 'Buduruvagala is significant because it represents an anomalous episode of Mahayana and Vajrayana influence in predominantly Theravada Sri Lanka, possibly connected to South Indian Mahayana contacts during the Pandyan political period. Its remoteness through rubber and paddy fields has kept it remarkably uncrowded, making it one of the most atmospheric ancient sites in the country.', '["historical-monument","Buddhist","Archaeological","Heritage","Hill Country"]', 'Bu-du-ru-va-ga-la Rock Tem-ple', '15-metre rock-cut Buddha, 8th century Mahayana, rare female Bodhisattva, jungle cliff setting, Wellawaya', 6.6169, 80.7453);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_yapahuwa', 'Yapahuwa Rock Fortress', 'archaeological_site', '13th Century AD', 'Yapahuwa was the royal capital of Sri Lanka for a brief but critical period between 1272 and 1284 AD, when King Bhuvanekabahu I established his court atop a massive 90-metre granite rock to protect the Sacred Tooth Relic of the Buddha from South Indian Pandyan invasions. The rock rises dramatically from the surrounding flat jungle plains, making it a natural fortress of extraordinary strategic value.', 'The ornate stairway leading to the upper palace is Yapahuwa''s crowning glory — a masterpiece of 13th-century Sinhalese decorative stonework with elaborately carved balustrades featuring lions, dwarves, and foliage in a style blending Sinhalese and South Indian artistic traditions. The stairway arch and window of the Lion Palace at the summit are the most refined decorative stone carvings of the late Sinhalese medieval period.', 'The Tooth Relic was stolen by Pandyan invaders from Yapahuwa in 1284 and recovered only years later — an event that precipitated the capital''s abandonment. The beautiful carved stone window from Yapahuwa''s palace now stands in the National Museum in Colombo as one of the finest medieval Sinhalese artefacts. The fortress is a favourite of archaeology enthusiasts who relish the reward of the summit view.', '["historical-monument","Archaeological","Heritage","Cultural Triangle","Medieval"]', 'Ya-pa-hu-wa Rock For-tress', '13th century royal capital, Sacred Tooth Relic fortress, ornate carved stairway, Pandyan invasions, 90-metre granite rock', 8.0523, 80.3478);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_nalanda_gedige', 'Nalanda Gedige', 'archaeological_site', '8th–11th Century AD', 'Nalanda Gedige is one of the most architecturally unique temples in Sri Lanka — a stone structure that perfectly blends Sinhalese Buddhist and South Indian Hindu architectural styles in a synthesis found nowhere else in the country. Built between the 8th and 11th centuries, it incorporates explicit Tantric carvings alongside Buddhist imagery, making it a testament to an era of remarkable religious syncretism.', 'The temple is constructed from dressed granite blocks assembled without mortar in the South Indian nagara shikhara (tower) tradition, yet the ground plan follows Sinhalese Buddhist conventions. The structure features erotic carvings in the tradition of Indian temple sculpture, alongside images of the Buddha and Bodhisattvas. It was partially dismantled and reassembled on higher ground when the Nalanda reservoir was built nearby, preserving it from flooding.', 'Nalanda Gedige is unique in South Asian religious architecture — no other structure in Sri Lanka shows such a thoroughgoing blend of Hindu and Buddhist traditions in both iconography and building form. It is believed to have been a centre for Tantric practice, a rare strand of religious thought that briefly influenced Sri Lankan Buddhism before Theravada orthodoxy reasserted itself in the Polonnaruwa period.', '["historical-monument","Archaeological","Heritage","Unique","Cultural Triangle"]', 'Na-lan-da Ge-di-ge', 'Unique Hindu-Buddhist fusion temple, 8th century, erotic Tantric carvings, reassembled after reservoir, Central Province', 7.6497, 80.8433);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_katharagama', 'Katharagama Sacred City', 'religious_site', 'Ancient (pre-Christian era)', 'Katharagama is one of the most sacred pilgrimage destinations in Sri Lanka, revered by Buddhists, Hindus, Muslims, and indigenous Veddah people alike. The city is home to the Kiri Vehera stupa (2nd century BC) and the Maha Devale — the primary shrine to the god Skanda (Murugan/Kataragama Deviyo), whose power is considered so immediate that devotees perform extreme acts of physical penance in his honour.', 'The sacred precinct comprises the Maha Devale shrine complex (where the golden casket relic of Skanda is kept), the ancient Kiri Vehera Buddhist stupa (one of the oldest in the south), a mosque honouring the Islamic saint Khizr, and ceremonial bathing ghats on the Menik Ganga river. The complex is architecturally modest but spiritually charged, reflecting its multi-faith nature.', 'The Katharagama Esala Festival each July–August is one of the most intense religious events in Asia — thousands of devotees perform fire-walking, hook-swinging (vel kavadi), tongue and cheek piercing, and rolling prostrations as acts of devotion to Skanda. The indigenous Veddah people, Sri Lanka''s original inhabitants, regard Katharagama as their most sacred site. Located near Yala National Park, pilgrims often encounter wild elephants on the road.', '["religious-temple","Pilgrimage","Heritage","Multi-faith","South Sri Lanka"]', 'Kath-a-ra-ga-ma Sa-cred Ci-ty', 'Multi-faith pilgrimage, Buddhist Hindu Muslim Veddah, fire-walking festival, Skanda deity, 2nd century BC stupa', 6.4151, 81.3342);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_mulgirigala', 'Mulgirigala Rock Temple', 'religious_site', '2nd Century BC', 'Mulgirigala is a dramatic rock monastery rising 200 metres from the southern lowland plains near Tangalle, comprising a series of cave temples cut into the rock face at different levels, connected by steep stone staircases. Founded in the 2nd century BC, it houses some of the finest ancient Sinhalese murals in the south of the island. A Danish scholar''s discovery here in 1826 of a Pali manuscript helped decode the Buddhist chronicle Mahavamsa.', 'The complex comprises seven cave temples at progressively higher levels of the rock, each containing reclining and seated Buddha statues plastered and painted in bright colours. The uppermost dagoba at the rock summit dates to the 2nd century BC. The interior walls and ceilings of the caves are painted with Kandyan-period murals depicting Jataka tales (stories of the Buddha''s previous lives) in vivid, folk-art style.', 'Mulgirigala''s historical importance extends beyond its religious role: the Pali manuscript found here by Danish linguist Wilhelm Geiger''s predecessor was the key that unlocked the translation of the Mahavamsa — Sri Lanka''s ancient chronicle and one of the longest unbroken historical records in the world. The site remains an active temple with resident monks, combining living religious practice with extraordinary heritage.', '["religious-temple","Buddhist","Archaeological","Heritage","South Coast"]', 'Mul-gir-i-ga-la Rock Tem-ple', '2nd century BC cave temple, ancient Sinhalese murals, Mahavamsa manuscript discovery, seven cave levels, southern Sri Lanka', 6.0667, 80.75);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_dondra_lighthouse', 'Dondra Head Lighthouse', 'monument', 'British Colonial (1889)', 'Dondra Head Lighthouse stands at the southernmost point of Sri Lanka — and indeed the southernmost point of all of South Asia — where the Indian Ocean meets the Bay of Bengal. Built by the British in 1889, its 49-metre white granite tower is the tallest lighthouse in Sri Lanka and guides ships through one of the busiest sea lanes in the world. Below the lighthouse lie the ruins of the ancient Dondra Vishnu Temple.', 'The lighthouse is constructed from Portuguese-style interlocking granite blocks without mortar, rising in a tapering octagonal column to its lantern room 160 metres above sea level. The adjacent ruins of the 16th-century Dondra Vishnu Devale — one of the four sacred Vishnu shrines of Sri Lanka, destroyed by the Portuguese in 1578 — provide a haunting contrast to the practical Victorian engineering of the lighthouse.', 'Dondra (Devundara in Sinhalese, meaning ''City of the Gods'') was one of ancient Sri Lanka''s most sacred pilgrimage cities, home to the great Vishnu temple described in vivid detail by the 14th-century Moroccan traveller Ibn Battuta before its Portuguese destruction. The lighthouse headland is also the traditional point where southern Sri Lankan fishermen have launched their boats into the open ocean for centuries.', '["historical-monument","Heritage","Lighthouse","South Coast","Southernmost Point"]', 'Don-dra Head Light-house, De-vun-da-ra', 'Southernmost point of South Asia, 49-metre lighthouse 1889, ancient Vishnu temple ruins, Ibn Battuta mentioned, Indian Ocean meets Bay of Bengal', 5.9238, 80.5914);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_hummanaya', 'Hummanaya Blowhole', 'attraction', 'Natural Heritage', 'The Hummanaya Blowhole near Dikwella on Sri Lanka''s south coast is the second-largest blowhole in the world and the largest in Asia, shooting seawater up to 23 metres into the air when ocean swells are strong. The blowhole is a natural sea cave in the coastal rock that compresses incoming waves and forces them explosively upward through a narrow rock chimney.', 'The geological formation is entirely natural — a lava tube-like cavity in the coastal bedrock approximately 30 metres long and several metres in diameter, open to the sea at one end and narrowing to a rock chimney at the other. The surrounding coastline is dramatic, with wave-cut platforms, sea arches, and a viewing platform constructed above the blowhole for safe observation.', 'Hummanaya is a popular day-trip destination from Galle and Matara, drawing visitors particularly during the southwest monsoon season (May–September) when the swells are strongest and the blowhole most dramatic. The name ''Hummanaya'' derives from the Sinhala word for the whooshing sound the blowhole makes as air and water are expelled. Local legend connects the cave to sea spirits and marine mythology.', '["urban-park","Nature","South Coast","Unique","Natural Wonder"]', 'Hum-ma-na-ya Blow-hole, Dik-wel-la', 'Second largest blowhole in world, 23-metre water jets, largest in Asia, Dikwella south coast, strongest in monsoon season', 5.95, 80.565);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_uppuveli', 'Uppuveli Beach', 'beach', 'Contemporary', 'Uppuveli is a quiet, largely undeveloped beach 4 km north of Trincomalee town, offering calm, clear waters with easy access to snorkelling reefs and proximity to Pigeon Island National Park. The beach is backed by a small fishing village and several mid-range guesthouses. The War Cemetery adjacent to the beach honours over 360 Allied naval personnel who died in the Battle of Ceylon in 1942.', 'The Commonwealth War Cemetery at Uppuveli is an immaculately maintained British-style memorial garden containing the graves of sailors and airmen of the British Royal Navy and Royal Air Force killed when Japanese aircraft attacked Trincomalee harbour and sank HMS Hermes — the world''s first purpose-built aircraft carrier — on 9 April 1942. The graves are individually marked with white Portland stone.', 'Uppuveli''s War Cemetery connects the beach to one of the most significant naval engagements in South Asian waters during World War II. The wreck of HMS Hermes, lying in 50 metres of water off Trincomalee, is now one of the most visited wreck dive sites in Asia. The juxtaposition of the calm beach, active fishing village, and solemn war graves creates an unusually layered visitor experience.', '["beach","Heritage","East Coast","World War II","Diving"]', 'Up-pu-ve-li Beach, Trin-co-ma-lee', 'Calm east coast beach, World War II cemetery, HMS Hermes wreck diving, near Trincomalee, Pigeon Island base', 8.596, 81.213);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_delft_island', 'Delft Island (Neduntheevu)', 'attraction', 'Dutch Colonial / Ancient', 'Delft Island, known in Tamil as Neduntheevu (Long Island), is a remote flat coral island in the Palk Strait 35 km northwest of Jaffna, accessible only by ferry. Named by the Dutch after the city of Delft in the Netherlands, it remains one of the most starkly beautiful and least-visited islands in Sri Lanka, famous for its wild ponies — descendants of Dutch-imported horses — roaming freely across the bare limestone landscape.', 'The island features a Dutch fort (1645), a baobab tree believed to be over 500 years old (planted by Arab traders), ancient pigeon houses (dovecotes) built by the Dutch, fossilised coral formations, and a giant 400-year-old gateway arch standing isolated in a field. The landscape is flat, windswept, and almost treeless — a dramatically different environment from mainland Sri Lanka.', 'Delft Island''s wild ponies, stone walls built from coral blocks, ancient ruins, and extraordinary remoteness give it a quality unlike anywhere else in Sri Lanka. The island''s inhabitants maintain Tamil Hindu traditions largely unchanged by modernisation. The ferry journey from Kurikadduwan through the shallow, turquoise Palk Strait waters is an experience in itself, with dolphins frequently accompanying boats.', '["historical-monument","Heritage","North Sri Lanka","Island","Unique"]', 'Delft Is-land, Ne-dun-thee-vu', 'Wild Dutch ponies, remote coral island, Dutch fort 1645, 500-year-old baobab, 35 km from Jaffna by ferry', 9.5463, 79.6878);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_kalpitiya', 'Kalpitiya Peninsula', 'beach', 'Natural Heritage / Colonial', 'Kalpitiya is a narrow peninsula on Sri Lanka''s northwest coast, flanked by the Indian Ocean and the Puttalam Lagoon, fast becoming the country''s premier destination for kite surfing and dolphin and whale watching. Between November and April, spinner dolphins gather in pods of hundreds in the waters off Kalpitiya, and blue and sperm whales pass close to shore making it one of Asia''s top cetacean hotspots.', 'The peninsula features a Portuguese-era fort built in 1667, later modified by the Dutch, that still stands guard over the Kalpitiya harbour. The surrounding Bar Reef Marine Sanctuary — the largest coral reef in Sri Lanka at 307 square kilometres — is protected within the Sri Lanka national park system. Traditional fishing villages using outrigger canoes line the lagoon shore.', 'Kalpitiya''s consistent strong winds from November to April have made it one of the top five kite surfing destinations in Asia, attracting international enthusiasts. The Bar Reef Marine Sanctuary protects an exceptional diversity of corals and marine life including dugong — sea mammals related to manatees — making it one of the last dugong habitats in South Asia. The peninsula''s Dutch fort reflects the strategic importance of this coastline for colonial spice trade routes.', '["beach","Wildlife","West Coast","Kite Surfing","Marine"]', 'Kal-pi-ti-ya Pen-in-su-la', 'Top 5 Asia kite surfing, 500 spinner dolphins, blue whale watching, Bar Reef Marine Sanctuary, dugong habitat', 8.2333, 79.7833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_tissamaharama', 'Tissamaharama', 'archaeological_site', '3rd Century BC', 'Tissamaharama is an ancient royal city in southeastern Sri Lanka, serving as the capital of the Ruhuna Kingdom for centuries. Founded in the 3rd century BC, it was the base from which King Dutugamunu launched his campaigns to reunite Sri Lanka under Sinhalese Buddhist rule. The city centres on the vast Tissa Wewa reservoir and three massive ancient stupas, and serves today as the gateway town to Yala National Park.', 'The three ancient stupas — Tissamaharama Dagoba, Sandagiri Vehera, and Yatala Vehera — are all within walking distance of each other and have been restored to their gleaming white condition. Tissamaharama Dagoba, the largest, is 55 metres high and was built by King Kavantissa in the 2nd century BC to house relics of the Buddha. The ancient Tissa Wewa tank remains a living reservoir used for irrigation.', 'Tissamaharama holds a pivotal place in Sri Lankan national identity as the staging ground for King Dutugamunu''s legendary military campaign against the Chola invaders — a defining episode in the Mahavamsa chronicle. The town is also associated with the legend of Princess Viharamahadevi, who was offered to the sea as a sacrifice from this coast and washed ashore at Kelaniya. Today it serves as the main safari town for Yala, Bundala, and Wirawila national parks.', '["historical-monument","Buddhist","Archaeological","Heritage","South Coast"]', 'Tis-sa-ma-ha-ra-ma', '3rd century BC royal capital, King Dutugamunu, three ancient white stupas, Tissa Wewa reservoir, Yala safari gateway', 6.2833, 81.2833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_rekawa', 'Rekawa Turtle Beach', 'beach', 'Natural Heritage / Conservation', 'Rekawa Beach near Tangalle is one of Sri Lanka''s most important sea turtle nesting beaches, where five species of sea turtles — green, leatherback, loggerhead, olive ridley, and hawksbill — come ashore to nest between April and September. The Rekawa Turtle Conservation Project, established in 1996, is one of Asia''s longest-running community-based marine conservation programmes.', 'The beach is a 3 km stretch of dark sand backed by coastal scrub vegetation. The conservation project operates a simple beach hut monitoring station where rangers watch for nesting turtles each night from dusk onwards. Visitors can join guided night walks to observe the nesting process under red light (to avoid disturbing the turtles), witnessing one of nature''s most ancient and profound rituals.', 'Rekawa''s success story lies in its community model — local villagers who once collected turtle eggs for food are now employed as conservation rangers, turning poaching incentives into protection incentives. Leatherback turtles nesting here can weigh 900 kilograms — the largest reptiles on Earth. The project has significantly increased hatchling survival rates and is studied internationally as a model for marine conservation economics.', '["beach","Wildlife","South Coast","Conservation","Turtle Nesting"]', 'Re-ka-wa Tur-tle Beach', 'Five turtle species nesting, leatherback 900kg world''s largest reptile, night watching tours, community conservation, near Tangalle', 6.0333, 80.8667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_madhu_church', 'Our Lady of Madhu Church', 'religious_site', '17th Century (1670)', 'Our Lady of Madhu is the most sacred Catholic pilgrimage site in Sri Lanka and one of the most important in Asia, drawing over 500,000 pilgrims annually to a remote jungle shrine in Mannar District. The miraculous statue of Our Lady of Madhu has been a site of veneration since 1670, when Sinhalese Catholics fled Portuguese-to-Dutch religious persecution and carried the statue to safety through the jungle, establishing a shrine where they settled.', 'The current church is a large white Gothic-style basilica with a high bell tower, rebuilt in its current form in the late 19th century. The interior houses the miraculous statue — a beautifully carved figure of Our Lady with the infant Jesus — in a richly decorated side chapel. The surrounding grounds accommodate vast numbers of pilgrims in temporary shelters during feast days.', 'Madhu Church carries extraordinary significance as a place of refuge and survival — throughout Sri Lanka''s civil conflict (1983–2009), it became a sanctuary where tens of thousands of civilians from both sides sought shelter, with an informal truce observed even during active fighting. The church compound sheltered up to 450,000 displaced people at various points, representing a unique example of sacred space transcending political violence.', '["religious-temple","Pilgrimage","Heritage","Christian","North Sri Lanka"]', 'Our La-dy of Ma-dhu Church', 'Most sacred Catholic shrine Sri Lanka, 500,000 annual pilgrims, 1670 miraculous statue, civil war sanctuary, Mannar district jungle', 8.7333, 79.9167);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_ramboda_falls', 'Ramboda Falls', 'attraction', 'Natural Heritage', 'Ramboda Falls is one of the most spectacular and accessible waterfalls in Sri Lanka, dropping 109 metres in three cascades through a lush gorge on the road between Kandy and Nuwara Eliya. It is the 11th highest waterfall in Sri Lanka and one of the most visited, situated close to the A5 highway that millions of travellers use to access the hill country.', 'The waterfall drops in three distinct stages through a deep forested gorge, with the middle section being the most dramatic — a near-vertical free-fall of approximately 75 metres. A pedestrian suspension bridge spans the gorge offering a direct eye-level view of the middle cascade. The surrounding slopes are covered in tea estates that form the visual backdrop to the falls.', 'Ramboda sits in the heart of the highland tea country, and the tea estates visible from the falls are among the highest-altitude tea gardens in Sri Lanka. The nearby Ramboda Pass at 1,238 metres was historically a strategic route connecting the Kandyan highlands to the lower hill country. The waterfall itself is sacred to the local Tamil plantation community who conduct annual ceremonies at its base.', '["urban-park","Nature","Waterfall","Hill Country","Tea Country"]', 'Ram-bo-da Falls', '109-metre three-cascade waterfall, suspension bridge view, Kandy to Nuwara Eliya road, tea estate backdrop, 11th highest in Sri Lanka', 7.0733, 80.7067);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_gregory_lake', 'Gregory Lake Nuwara Eliya', 'attraction', 'British Colonial (1873)', 'Gregory Lake is an artificial reservoir in the heart of Nuwara Eliya town, created in 1873 by British Governor Sir William Henry Gregory (also founder of the National Museum) by damming the Nanu Oya stream. Surrounded by manicured lawns, rose gardens, and colonial-era bungalows, it is the social centrepiece of Sri Lanka''s most British hill town — a place of boating, cycling, and the famous April Season festivities.', 'The lake covers approximately 20 hectares and is bounded by a promenade walk, boat jetty, and the Victoria Park lawns. The surrounding landscape includes the Hill Club golf course, the Grand Hotel (1891), and Victorian-era bungalows with English country garden characteristics. Pedal boats, kayaks, and speed boats operate on the lake, and horse rides are available on the promenade.', 'Gregory Lake is the epicentre of Nuwara Eliya''s famed April Season — ten days of horse racing, vintage car rallying, boat racing, and garden competitions held each April that preserve Victorian colonial leisure traditions with remarkable fidelity. The lake''s reflection of the surrounding misty hills and colonial architecture creates the most quintessentially ''Little England'' scene in Sri Lanka.', '["urban-park","Heritage","Hill Country","Colonial","Family"]', 'Greg-o-ry Lake Nu-wa-ra E-li-ya', '1873 colonial reservoir, April Season boating and racing, Little England atmosphere, Victorian promenade, Nuwara Eliya centrepiece', 6.9738, 80.7757);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_kelaniya_temple', 'Kelaniya Raja Maha Vihara', 'religious_site', '3rd Century BC', 'Kelaniya Raja Maha Vihara is one of the most sacred Buddhist temples in Sri Lanka, located 11 km east of Colombo on the banks of the Kelaniya River. According to the Mahavamsa, the Buddha himself visited Kelaniya during his third and final visit to Sri Lanka in the 6th century BC, sitting on a gem-studded throne to preach to the Naga king Maniakkhika. The temple was rebuilt in its current ornate form in the 20th century.', 'The temple features a distinctive low, white dagoba in the unusual ''heap of paddy'' form — a flattened shape unique to Kelaniya, said to enshrine the gem-studded throne on which the Buddha sat. The image house walls are covered in extraordinary 20th-century murals painted by artist Solias Mendis depicting scenes from Buddhist history and Jataka tales with a blend of traditional and art-deco aesthetics.', 'The Duruthu Perahera festival held at Kelaniya each January (on the Duruthu full moon poya day) is one of the five great processions of Sri Lanka, commemorating the Buddha''s visit. It features over 70 elaborately decorated elephants, Kandyan dancers, and fire performers processing through the night. The temple attracts the largest daily attendance of any temple in Sri Lanka, drawing pilgrims from across the island every poya (full moon) day.', '["religious-temple","Buddhist","Heritage","Colombo","Pilgrimage"]', 'Ke-la-ni-ya Ra-ja Ma-ha Vi-ha-ra', 'Buddha visited in person 6th century BC, unique flattened dagoba, Solias Mendis murals, Duruthu Perahera 70 elephants, 11 km from Colombo', 6.955, 79.9212);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_lunugamvehera', 'Lunugamvehera National Park', 'national_park', 'Established 1995', 'Lunugamvehera National Park is a relatively recently gazetted wildlife reserve in southeastern Sri Lanka, centred on the Lunugamvehera Reservoir. It forms a critical wildlife corridor connecting Yala and Udawalawe national parks, allowing elephant herds and other animals to migrate freely between the three protected areas. The park has one of the highest elephant densities in Sri Lanka.', 'The park''s dominant feature is the Lunugamvehera Reservoir, a large irrigation tank whose shores attract concentrations of waterbirds, crocodiles, and elephants. The surrounding habitat is a mosaic of dry scrub jungle, riverine forest, and open grassland. The reservoir''s waters support large populations of mugger crocodiles and freshwater fish that in turn sustain otters, fishing cats, and waterbirds.', 'Lunugamvehera''s role as a wildlife corridor is ecologically critical — without it, elephant populations in Yala and Udawalawe would be genetically isolated, threatening their long-term viability. The park is less visited than its famous neighbours, making it an excellent choice for visitors seeking authentic wildlife encounters without crowds. Large herds of elephants congregating at the reservoir edges during dry season create spectacular viewing opportunities.', '["urban-park","Wildlife","Elephant","Safari","South Sri Lanka"]', 'Lu-nu-gam-ve-he-ra Na-tion-al Park', 'Elephant corridor between Yala and Udawalawe, large reservoir, crocodiles and waterbirds, less crowded safari, southeastern Sri Lanka', 6.3333, 81.2667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_beira_lake', 'Beira Lake Colombo', 'attraction', 'Portuguese / Dutch Colonial (16th Century)', 'Beira Lake is the historic heart of Colombo, a 65-hectare artificial lake created by the Portuguese in the 16th century as a defensive moat protecting their colonial fort. Developed further by the Dutch and British, it became the commercial waterway of the colonial city. Today it is surrounded by Colombo''s most iconic buildings and serves as a public park, rowing venue, and floating market hub.', 'The lake is connected to the sea by canal, allowing tidal fluctuation that has historically maintained its water level. Its shores are lined with the Gangaramaya Temple, the Seema Malaka (a floating temple designed by architect Geoffrey Bawa on an island in the lake), the Colombo City Centre mall, and colonial-era government buildings. A promenade circuit allows walking and cycling around the lake perimeter.', 'The Seema Malaka — Geoffrey Bawa''s floating Buddhist sanctuary on Beira Lake — is one of the most celebrated works of Sri Lankan architecture, a serene island temple reached by footbridge whose design responds perfectly to its water setting. The Navam Perahera procession from Gangaramaya Temple circles the lake shores each February with 50 decorated elephants in one of Colombo''s most spectacular annual events.', '["historical-monument","Heritage","Colombo","Urban","Colonial"]', 'Bei-ra Lake Co-lom-bo', 'Portuguese colonial moat 1500s, Geoffrey Bawa''s floating Seema Malaka temple, Navam Perahera procession, 65 hectares, heart of Colombo', 6.9169, 79.8569);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_panduwasnuwara', 'Panduwasnuwara Ancient City', 'archaeological_site', '5th Century BC', 'Panduwasnuwara is one of the earliest known urban settlements in Sri Lanka, dating to approximately the 5th century BC — making it contemporary with the earliest Anuradhapura occupation. The site contains the ruins of a royal palace complex, a circular citadel, a water garden, moat, and a series of monastic structures, representing the full infrastructure of an early Sri Lankan city-state.', 'The most remarkable structure at Panduwasnuwara is a unique circular palace (''circular palace'' in the Sri Lankan chronicles), surrounded by a moat — a building form with no parallel in South Asian archaeology. The site also features an ancient water garden with ornamental ponds and channels, a substantial dagoba, and the remains of a city wall enclosing the royal precinct.', 'Panduwasnuwara is associated in the chronicles with King Pandukabhaya (437–367 BC), the unifier of ancient Sri Lanka and founder of Anuradhapura as the royal capital. Some scholars identify this site as his pre-Anuradhapura capital. The site remains under-explored compared to the famous Cultural Triangle sites, making it an authentic archaeological discovery experience for adventurous travellers.', '["historical-monument","Archaeological","Heritage","Ancient","Cultural Triangle"]', 'Pan-du-was-nu-wa-ra An-cient Ci-ty', '5th century BC early Sri Lankan city, unique circular palace, moat and water garden, King Pandukabhaya connection, hidden gem archaeology', 7.8167, 80.3833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_point_pedro', 'Point Pedro', 'attraction', 'Ancient to Contemporary', 'Point Pedro is the northernmost tip of Sri Lanka, where the Palk Strait narrows to just 40 km separating the island from India. A small lighthouse marks the extremity of the island. The town is a bustling Tamil fishing community and the gateway to the Jaffna Peninsula''s northern coast. On the clearest days, the coast of Tamil Nadu in India is visible from here.', 'The Point Pedro Lighthouse, built during the British colonial period, is a modest white tower that has guided ships through the notoriously shallow Palk Strait for over a century. The surrounding coastline is rocky and windswept, with traditional catamaran fishing boats pulled up on the shore. A Hindu coastal shrine marks the spiritual significance locals attach to this liminal land''s-end point.', 'Point Pedro holds symbolic importance as the geographic extremity of the island — completing the traditional pilgrimage circuit of Sri Lanka''s four cardinal points: Dondra Head (south), Colombo (west), Sangaman Kanda (east), and Point Pedro (north). The local fishing community has maintained this northern shore for centuries, and the nearby Vallipuram Vishnu Temple is one of the oldest in the Jaffna Peninsula.', '["historical-monument","North Sri Lanka","Lighthouse","Heritage","Northernmost Point"]', 'Point Pe-dro', 'Northernmost tip of Sri Lanka, 40 km from India, British lighthouse, Tamil fishing community, see Tamil Nadu on clear days', 9.8167, 80.2333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_nainativu', 'Nainativu Island', 'religious_site', 'Ancient (pre-5th Century AD)', 'Nainativu is a small island in the Palk Strait accessible only by boat from Kurikadduwan pier north of Jaffna, housing two of the most sacred pilgrimage sites in northern Sri Lanka. The Nagadipa Buddhist Temple marks the spot where the Buddha is said to have visited during his second journey to Sri Lanka to settle a dispute between Naga kings; alongside it stands the Nainativu Nagapooshani Amman Kovil — one of the holiest Hindu temples in the country.', 'The Buddhist Nagadipa Purana Vihara is a gleaming white stupa set in a small compound at the island''s centre, traditionally housing relics from the Buddha''s era. The adjacent Nagapooshani Amman Kovil is a colourful Dravidian-style temple dedicated to the goddess Bhuvaneswari, renowned for its gold-plated sanctum and ornate gopuram. The two temples stand within metres of each other, embodying Sri Lanka''s tradition of religious coexistence.', 'The boat journey to Nainativu — past flocks of seabirds, through shallow turquoise waters with visible coral — is as memorable as the destination. The island receives thousands of pilgrims daily from both Buddhist and Hindu traditions. The Naga Pooshani Amman temple festival draws over 100,000 Tamil Hindu devotees annually. This small island perfectly encapsulates the multi-religious character of Sri Lanka''s north.', '["religious-temple","Buddhist","Hindu","Pilgrimage","North Sri Lanka"]', 'Nai-na-ti-vu Is-land, Na-ga-di-pa, Na-ga-poo-sha-ni Am-man', 'Buddha''s second Sri Lanka visit, sacred to Buddhists and Hindus, island accessible only by boat, 100,000 pilgrims, Jaffna north', 9.7667, 79.7833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_keerimalai', 'Keerimalai Hot Springs', 'attraction', 'Ancient (pre-Christian era)', 'Keerimalai is a coastal hot spring complex at the northernmost shore of Sri Lanka, where natural spring water at 28–32°C flows directly into the sea. The springs have been used for therapeutic bathing for over 2,000 years, with ancient Tamil Siddha medical texts describing their curative properties. A legend tells that a princess afflicted with a horse-like facial deformity was cured after bathing in these waters.', 'The hot springs are channelled into gender-segregated stone bathing pools built at the sea''s edge, enclosed by walls for modesty. The Maviddapuram Kandaswamy Kovil — a significant Hindu temple built over the spring source — is one of the Pancha Ishwarams of Tamil tradition. Its 5-tiered gopuram tower rises above the coastal landscape.', 'Keerimalai''s springs are believed to be connected to a freshwater source deep beneath the ocean floor, rising through a limestone aquifer. Local Tamil communities have bathed here for generations as both spiritual ritual and medical treatment. The springs survived the civil conflict largely intact and are today a point of cultural reconnection for Sri Lanka''s Tamil community with their ancient northern heritage.', '["religious-temple","Hindu","Heritage","North Sri Lanka","Wellness"]', 'Keer-i-ma-lai Hot Springs', 'Ancient therapeutic hot springs, princess legend, 2000-year history, Kandaswamy temple, northernmost Sri Lanka coast', 9.8167, 80.0333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_sasseruwa', 'Sasseruwa Buddha Statue', 'archaeological_site', '1st–4th Century AD', 'The Sasseruwa Buddha is a magnificent 12-metre rock-cut standing Buddha carved from a granite cliff face in the Kurunegala District, traditionally considered the ''unfinished'' twin of the Aukana Buddha. Legend holds that the two statues were carved simultaneously by a master and his student in a competition — the student''s Sasseruwa statue was abandoned when the master completed Aukana first. This makes Sasseruwa one of the oldest attempted rock-cut Buddhas in Sri Lanka.', 'The statue is carved in the abhaya mudra pose from a vertical granite face, standing within a deep rock shelter. Unlike the pristine Aukana Buddha, Sasseruwa''s surface shows the marks of unfinished chiselling, particularly around the robe folds and face — supporting the legend of its incompletion. A small cave monastery complex surrounds the statue with ancient inscriptions and meditation cells.', 'Sasseruwa is considered an active place of veneration by local Buddhist communities, with a resident monk maintaining the site. Its relative obscurity compared to Aukana makes it a rewarding off-the-beaten-path destination. The surrounding forested hills harbour wild elephants, and the rock shelter monastery gives a vivid impression of ancient monastic life in the North Central jungle.', '["historical-monument","Buddhist","Archaeological","Heritage","Cultural Triangle"]', 'Sas-se-ru-wa Bud-dha Sta-tue', '12-metre unfinished rock Buddha, twin of Aukana, master versus student legend, ancient cave monastery, North Central jungle', 8.0342, 80.5233);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_ridi_viharaya', 'Ridi Viharaya', 'religious_site', '2nd Century BC', 'Ridi Viharaya (Silver Temple) is a cave temple of exceptional historical significance, founded in the 2nd century BC by King Dutugamunu after silver ore was discovered at this location — providing the finances needed to build the great Ruwanwelisaya stupa at Anuradhapura. The temple complex contains extraordinarily rich Kandyan-period interiors with Dutch-imported blue-and-white Delft tiles covering the walls — an extraordinary fusion of Buddhist and European decorative arts.', 'The main cave shrine features walls entirely lined with authentic 17th-century Dutch Delft tiles, donated by the Dutch East India Company as part of a trade agreement — creating a startlingly beautiful combination of Buddhist imagery and Dutch chinoiserie patterns. The image house also contains an unusual ivory-seated Buddha and some of the finest Kandyan-period paintings in Sri Lanka.', 'Ridi Viharaya''s Dutch tiles are unique in Sri Lankan religious architecture — no other temple has anything comparable, making it one of the most visually unexpected heritage experiences in the country. The silver ore discovery here is one of the defining events in Sri Lankan Buddhist history, enabling King Dutugamunu to complete his ambitious building programme at Anuradhapura. The temple remains active with monks in residence.', '["religious-temple","Buddhist","Heritage","Unique","Archaeological"]', 'Ri-di Vi-ha-ra-ya, Silver Tem-ple', 'Silver Temple, Dutch Delft tiles lining walls, 2nd century BC, King Dutugamunu silver discovery, unique Buddhist-European fusion', 7.6833, 80.5167);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_arankele', 'Arankele Forest Monastery', 'archaeological_site', '6th–7th Century AD', 'Arankele is a remote forest monastery complex in the Kurunegala District, founded in the 6th–7th centuries AD as a hermitage for meditation monks following the Aranavasi (forest-dweller) tradition. Its ruins — stone meditation walkways, platforms, bathing pools, and cisterns — are largely unexcavated and still partially engulfed by jungle, creating one of the most atmospheric ancient sites in Sri Lanka.', 'The complex features raised stone meditation walkways (identical in design to those at Ritigala), double-platform monk residences, and a network of cisterns and ponds fed by stone-channelled rainwater. The engineering precision of the walkways and water management systems, built without mortar, demonstrates the high technical skill of ancient Sinhalese builders even in a remote forest setting.', 'Arankele represents the Aranavasi monastic tradition — forest monks who deliberately chose isolation from mainstream monastery life to pursue intense meditation practice. The site shares architectural DNA with Ritigala, suggesting a connected network of forest hermitages across north-central Sri Lanka in the early medieval period. Its near-complete absence from tourist circuits makes it one of the most authentic ancient sites in the country.', '["historical-monument","Buddhist","Archaeological","Heritage","Hidden Gem"]', 'A-ran-ke-le For-est Mon-as-ter-y', '6th century forest hermitage, meditation walkways, Aranavasi monk tradition, jungle-engulfed ruins, unexcavated hidden gem', 7.7697, 80.3748);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_ambuluwawa', 'Ambuluwawa Biodiversity Complex', 'attraction', 'Contemporary', 'Ambuluwawa is a 1,319-metre hilltop biodiversity complex near Gampola in the Kandy District, featuring a uniquely designed multi-religious tower that houses four separate religious shrines — Buddhist, Hindu, Muslim, and Christian — within a single spiral structure. The surrounding biodiversity reserve protects rare montane forest species. The spiral tower is a remarkable piece of contemporary Sri Lankan architecture.', 'The Ambuluwawa Tower rises in a tapering concrete spiral from the hilltop, with each level housing a different religious shrine accessed by an external spiral staircase that winds around the outside of the tower. From the summit platform, a 360-degree panorama encompasses the Kandy valley, Knuckles Range, Adam''s Peak, and on clear days the coastline. The tower''s form resembles a traditional Sri Lankan dagoba fused with a lighthouse.', 'Ambuluwawa''s multi-faith tower is a deliberate architectural statement of religious harmony in a country that has experienced significant religious tension. The four religious communities share the hilltop and its facilities, making it a working symbol of inter-faith coexistence. The biodiversity reserve on the slopes shelters medicinal plant species documented in ancient Sinhala herbal manuscripts.', '["religious-temple","Urban","Nature","Multi-faith","Hill Country"]', 'Am-bu-lu-wa-wa Bi-o-di-ver-si-ty Com-plex', 'Multi-faith spiral tower, Buddhist Hindu Muslim Christian shrines, 1319 metres, panoramic views, Kandy district', 7.2333, 80.6167);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_devon_falls', 'Devon Falls', 'attraction', 'Natural Heritage', 'Devon Falls is one of Sri Lanka''s most spectacular highland waterfalls, dropping 97 metres through a narrow gorge on the slopes near Hatton in the Nuwara Eliya District. Named after a former British coffee planter named Devon who owned the surrounding estate, the falls plunge through a lush curtain of tropical vegetation. It is located close to the equally dramatic St Clair''s Falls, together forming one of the finest waterfall viewing areas in the hill country.', 'The falls drop in a single powerful column from a rocky notch in the ridge, narrowing as it falls before spreading into a wide plunge pool hidden in the gorge below. The viewing point is accessible from the Hatton–Nuwara Eliya road, with the falls visible across the gorge through tea estate vegetation. A short walk through a working tea estate leads to a closer viewpoint.', 'Devon Falls and the adjacent St Clair''s Falls sit within working tea estates, creating a landscape that perfectly combines Sri Lanka''s colonial tea heritage with its dramatic highland waterfalls. The tea estate pathways passing the falls are used daily by Tamil estate workers, offering visitors a window into the daily life of Sri Lanka''s plantation communities — a social world that has changed remarkably little since the colonial era.', '["urban-park","Nature","Waterfall","Hill Country","Tea Country"]', 'Dev-on Falls Hat-ton', '97-metre single drop waterfall, named after British planter, near St Clair''s Falls, Hatton tea country, Nuwara Eliya district', 6.9167, 80.5667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_st_clairs_falls', 'St Clair''s Falls', 'attraction', 'Natural Heritage', 'St Clair''s Falls, known as the ''Niagara of Sri Lanka,'' is a broad, powerful waterfall on the Kothmale Oya river near Dickoya in the Nuwara Eliya highlands. It consists of two adjacent falls — Upper St Clair (80 metres) and Lower St Clair (50 metres) — that together create a wide curtain of white water across a 30-metre-wide rock face, making it the widest waterfall in Sri Lanka.', 'The falls flow over a broad basalt ledge, creating a wide, multi-channelled cascade rather than a single narrow column. The surrounding tea estates of the Bogawantalawa Valley frame the falls with bright green geometric tea rows that contrast dramatically with the white foam. The viewing terrace above the falls is on the main Hatton road, making it one of the most photographed waterfalls in Sri Lanka.', 'St Clair''s is set within the Bogawantalawa Valley — known as the ''Golden Valley of Tea'' — which produces some of the finest high-grown Ceylon teas in the world. The estates here, many established in the 1870s, have been producing tea continuously for 150 years. The valley was once an important coffee-growing region before the devastating coffee blight of 1869 wiped out the entire crop and forced a switch to tea.', '["urban-park","Nature","Waterfall","Hill Country","Tea Country"]', 'Saint Clairs Falls, Ni-ag-a-ra of Sri Lanka', 'Niagara of Sri Lanka, widest waterfall, two falls 80 and 50 metres, Bogawantalawa Golden Valley of Tea, Dickoya highlands', 6.9167, 80.5833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_udawattakele', 'Udawattakele Forest Reserve', 'national_park', 'Ancient Royal Forest', 'Udawattakele (Upper Royal Forest) is a 104-hectare cloud forest reserve directly above Kandy city, serving as the royal forest of the Kandyan kings and later maintained by British colonial governors as a protected natural zone. It shelters endemic birds and giant squirrels within walking distance of Kandy''s city centre, and contains two ancient hermitage caves used by meditating monks over centuries.', 'The forest contains two ancient cave hermitages — Lady Horton''s Walk cave and the Asgiriya cave — where stone-cut inscriptions record royal donations to forest monks dating to the 1st–3rd centuries AD. The forest canopy reaches 25–30 metres, sheltering an understorey rich in epiphytic orchids, ferns, and mosses characteristic of Sri Lanka''s wet zone montane forests.', 'Udawattakele was the private royal forest of the Kandyan kings, forbidden to commoners and used for the king''s leisure and for royal monks'' meditation. British Governor Edward Barnes maintained it as a pleasure garden, adding walking paths still used today. The forest is habitat for the Sri Lanka highland bird assemblage — including the Sri Lanka bush warbler, Sri Lanka whistling thrush, and Layard''s parakeet — making it one of the best birding spots accessible from any Sri Lankan city.', '["urban-park","Wildlife","Heritage","Hill Country","Birdwatching"]', 'U-da-wat-ta-ke-le For-est Re-serve, Upper Roy-al For-est', 'Ancient Kandyan royal forest, 104 hectares above Kandy, endemic birds, 1st century cave inscriptions, walking distance from city', 7.2967, 80.6367);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_weherehena', 'Weherehena Temple', 'religious_site', 'Contemporary (20th Century)', 'Weherehena Temple near Matara is famous for its extraordinary underground diorama — a series of 80 tunnels decorated with over 3,000 painted plaster figures depicting scenes from the life of the Buddha, Buddhist cosmology, and Jataka tales. The temple is dominated by a 39-metre multi-tiered pagoda tower, the largest in southern Sri Lanka, visible from miles around.', 'The temple complex is architecturally eclectic and visually overwhelming — the main pagoda tower is covered in coloured glass and ceramic tiles, surrounded by a pantheon of large statues of deities and guardian figures. The underground labyrinth consists of narrow passages linking chambers, each completely painted and filled with brightly coloured figures illustrating Buddhist teachings in a folk-art style of extraordinary energy.', 'Weherehena''s underground diorama is unique in Sri Lanka — no other temple has attempted such an immersive visual teaching environment, clearly designed to make Buddhist cosmology accessible through dramatic visual storytelling. The temple draws pilgrims and tourists in equal measure, and its overwhelming visual richness has made it one of the most discussed temples in southern Sri Lanka. The complex is still growing, with new sections added regularly.', '["religious-temple","Buddhist","Heritage","Unique","South Coast"]', 'We-he-re-he-na Tem-ple Ma-ta-ra', '3000 plaster figures in 80 underground tunnels, 39-metre pagoda, Buddhist diorama, Matara, visually overwhelming pilgrimage site', 5.94, 80.5333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_maligawila', 'Maligawila Buddha Statue', 'archaeological_site', '7th Century AD', 'The Maligawila Buddha is the tallest ancient standing Buddha statue in Sri Lanka — a magnificent 10.5-metre figure carved from a single limestone block in the 7th century AD by Prince Aggabodhi of the Uda Rata kingdom. It stood in the ancient city of Maligawila until it collapsed and lay broken in the jungle for centuries before being painstakingly reassembled and re-erected in 1991.', 'The standing Buddha is carved in the abhaya mudra (blessing) pose from a single Kuruvita limestone block — an extraordinary feat of ancient quarrying and transport, as the stone was brought from a quarry 7 km distant. The statue was broken into 34 fragments when it toppled, and its 1991 restoration using traditional techniques is considered one of Sri Lanka''s most remarkable conservation achievements. A Bodhisattva statue of equal magnificence stands nearby.', 'Maligawila''s remote jungle location in the Monaragala District, far from the main tourist circuit, preserves an atmosphere of genuine discovery. The site contains the ruins of the ancient Maligawila monastery — inscriptions reveal it was gifted to the Sangha by Prince Aggabodhi as an act of merit-making. The combination of the colossal restored Buddha and the jungle-engulfed monastery ruins makes Maligawila one of Sri Lanka''s most rewarding off-the-beaten-path destinations.', '["historical-monument","Buddhist","Archaeological","Heritage","Hidden Gem"]', 'Ma-li-ga-wi-la Bud-dha Sta-tue', 'Tallest ancient Buddha in Sri Lanka, 10.5 metres, 7th century single limestone block, broken and restored 1991, remote Monaragala jungle', 6.95, 81.29);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_munneswaram', 'Munneswaram Temple', 'religious_site', 'Ancient (pre-Christian era)', 'Munneswaram is one of the five ancient pancha Ishwaram Shiva temples of Sri Lanka, located near Chilaw on the northwest coast. It is considered one of the oldest Hindu temples on the island, with origins attributed to the era of the Ramayana — tradition holds that Rama worshipped here to atone for having killed Ravana. The temple complex is among the most important Hindu pilgrimage sites in Sri Lanka.', 'The Munneswaram complex comprises five temples, with the main Munneswaram Shiva temple being the largest and oldest. The complex features a 100-metre-long columned mandapam (hall), a distinctive three-tiered gopuram, and shrines to Ganesh, Kali, and Vishnu within the compound. The Kali shrine is particularly famous for intense devotional practices during festival periods.', 'Munneswaram''s Kali shrine is renowned throughout Sri Lanka for its fire-walking ceremonies (thimithi), held annually in August–September, where thousands of devotees walk across burning coal as an act of devotion. The temple''s antiquity — mentioned in Dutch colonial records from the 1660s — and its association with the Ramayana make it a site of pan-Asian Hindu significance. The temple serves the large Tamil and Sinhalese Hindu communities of the northwest coast.', '["religious-temple","Hindu","Heritage","Pilgrimage","West Coast"]', 'Mun-nes-wa-ram Tem-ple Chi-law', 'Ancient Pancha Ishwaram Shiva temple, Rama worshipped here Ramayana, fire-walking festival, Chilaw northwest coast, 100-metre columned hall', 7.75, 79.8833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_wasgamuwa', 'Wasgamuwa National Park', 'national_park', 'Established 1984', 'Wasgamuwa National Park is a relatively undiscovered wildlife sanctuary in central Sri Lanka, centred on the Mahaweli River — the longest river in Sri Lanka. The park is home to one of the densest concentrations of Sri Lanka elephants outside Minneriya, with herds of 100+ regularly sighted. It also shelters leopards, sloth bears, mugger crocodiles, and an extraordinary diversity of waterbirds along the river.', 'The park''s landscape is shaped by the Mahaweli River and its tributaries, creating rich riparian habitats of riverine forest, reed beds, and sandy banks. Ancient irrigation tank ruins within the park reveal that this area was once cultivated land, abandoned over 1,000 years ago as political instability reduced the population. The park is accessible from Habarana or Kandy, with fewer visitor vehicles than Yala or Minneriya.', 'Wasgamuwa''s elephant population includes a significant proportion of tuskers — large male elephants with full ivory tusks — making it one of the best places in Asia to observe tusked bulls in the wild. The park''s low visitor numbers mean wildlife encounters are unhurried and intimate compared to Sri Lanka''s more famous parks. The riverside landscape at sunset, with elephants bathing in the Mahaweli River, is considered one of the finest wildlife spectacles in the country.', '["urban-park","Wildlife","Elephant","Safari","Central Sri Lanka"]', 'Was-ga-mu-wa Na-tion-al Park', 'Undiscovered elephant park, 100-plus herds, tusked bulls, Mahaweli River, less crowded than Yala, leopards and sloth bears', 7.7833, 80.9833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_gal_oya', 'Gal Oya National Park', 'national_park', 'Established 1954', 'Gal Oya National Park is the only park in Sri Lanka where safaris are conducted by boat, floating across the vast Senanayake Samudraya reservoir — the largest inland water body in the country. The reservoir is dotted with jungle-covered islands, and boat passengers observe elephants swimming between islands, crocodiles basking on shores, and rare waterbirds in an experience unlike any other safari in Asia.', 'The Senanayake Samudraya reservoir, completed in 1951, covers 9,085 hectares and was Sri Lanka''s first major post-independence irrigation project. The ancient Gal Oya Oya valley beneath the reservoir contained important archaeological sites — traces of the ancient Gal Oya civilisation — that were submerged during construction. The surrounding park protects 54,000 hectares of dry zone forest.', 'Gal Oya''s boat safari experience is considered one of the most extraordinary wildlife encounters in Asia — watching a herd of 30 elephants swim across a reservoir from island to island, with no roads or vehicles, creates a sense of witnessing nature completely on its own terms. The park shelters one of Sri Lanka''s most significant populations of the endemic purple-faced langur and is the eastern anchor of a critical wildlife corridor.', '["urban-park","Wildlife","Elephant","Boat Safari","East Sri Lanka"]', 'Gal O-ya Na-tion-al Park', 'Sri Lanka''s only boat safari, elephants swimming between islands, largest reservoir, 54,000 hectares, unique Asia experience', 7, 81.5);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_dambadeniya', 'Dambadeniya Ancient City', 'archaeological_site', '13th Century AD', 'Dambadeniya served as the royal capital of Sri Lanka from 1220 to 1272 AD, during the turbulent period of repeated South Indian invasions. King Vijayabahu III established the court here on a naturally fortified rocky outcrop, and his successors including Parakramabahu II — considered the greatest king of the medieval period — ruled from Dambadeniya and composed the celebrated Sinhala literary work Kavsilumina.', 'The ancient city features a two-storey image house with original paintings, a 300-metre relic house on the summit, the ruins of the royal palace complex, ancient stone steps carved into the rock face, and a well-preserved stupa. The surrounding rock face drops steeply on three sides, providing natural fortification. The Dalada Maligawa (Tooth Relic shrine) here predates the more famous Kandy temple by two centuries.', 'Dambadeniya is significant as the capital from which Sri Lanka successfully resisted Magha''s South Indian occupation and preserved the Tooth Relic. King Parakramabahu II''s achievement in expelling the Tamil Chandrabhanu''s invasions and reunifying the island is celebrated in the Sinhala chronicle Pujavaliya. The city also marks the beginning of Sri Lanka''s medieval Sinhalese literary renaissance.', '["historical-monument","Archaeological","Heritage","Medieval","Cultural Triangle"]', 'Dam-ba-de-ni-ya An-cient Ci-ty', '13th century royal capital, Parakramabahu II, Tooth Relic shrine, rock fortress, Sinhala literary renaissance, South Indian resistance', 7.66, 80.07);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_peak_wilderness', 'Peak Wilderness Sanctuary', 'national_park', 'Natural Heritage', 'Peak Wilderness Sanctuary (Sri Pada Wildlife Sanctuary) is a 224 square-kilometre protected zone surrounding Adam''s Peak in Sri Lanka''s central highlands, forming part of the UNESCO Central Highlands World Heritage Site. The sanctuary protects some of the richest biodiversity in Sri Lanka — over 100 endemic plant species grow here — and forms a critical watershed feeding numerous rivers.', 'The sanctuary''s terrain is dramatically varied — from lowland rainforest at 600 metres rising to the highland cloud forest zone above 1,800 metres surrounding Adam''s Peak summit. Ancient pilgrimage paths cutting through the sanctuary have been maintained for 1,000 years by successive generations of devotees. The forest contains several ancient rest houses (ambalamas) built for pilgrims that function to this day.', 'Peak Wilderness is significant both ecologically and spiritually — it protects the forest surrounding the most sacred peak in Sri Lanka while sheltering populations of leopard, sambar deer, purple-faced langurs, and hundreds of endemic bird species. The sanctuary also harbours several remote villages of traditional Veddah communities who maintain ancient forest-dwelling lifestyles. The combination of spiritual significance and biodiversity makes it one of the most complex landscapes in South Asia.', '["urban-park","UNESCO","Wildlife","Pilgrimage","Hill Country"]', 'Peak Wil-der-ness Sanc-tu-a-ry, Sri Pa-da Wild-life', 'UNESCO Central Highlands, surrounds Adam''s Peak, 100 endemic plant species, ancient pilgrimage paths, Veddah communities', 6.75, 80.6667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_habarana', 'Habarana Village', 'attraction', 'Ancient to Contemporary', 'Habarana is the strategic hub of the Cultural Triangle — a small village equidistant from Sigiriya, Polonnaruwa, Dambulla, and Anuradhapura, making it the ideal base for exploring Sri Lanka''s ancient sites. The Habarana Lake is famous for elephant sightings at dusk, and the surrounding village offers authentic Sri Lankan rural experiences including jeep safaris to Minneriya and Kaudulla national parks.', 'Habarana''s village character is shaped by its ancient tank (reservoir) system, paddy fields, and the surrounding dry zone scrub forest through which wild elephants move freely. The Habarana wewa (tank) is an ancient irrigation reservoir still functioning for rice cultivation. Traditional wattle-and-daub village houses and bullock-cart pathways through paddy give a vivid picture of timeless Sri Lankan rural life.', 'Habarana sits at the intersection of ancient Sri Lanka''s most important trade and pilgrimage routes. The surrounding jungle was historically the domain of the ancient Veddah people — Sri Lanka''s indigenous inhabitants — and traditional Veddah communities in nearby Dambana maintain cultural practices including honey-gathering, forest hunting, and ceremonial drumming that trace back thousands of years.', '["urban-park","Wildlife","Heritage","Cultural Triangle","Safari"]', 'Ha-ba-ra-na Vil-lage', 'Cultural Triangle safari hub, wild elephants at dusk, gateway to Sigiriya Polonnaruwa Dambulla Anuradhapura, ancient tank village', 8.0333, 80.75);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_kurunegala', 'Kurunegala Elephant Rock', 'attraction', 'Medieval (13th–14th Century)', 'Kurunegala served as the royal capital of Sri Lanka for 50 years in the 13th–14th centuries and is dominated by a series of massive granite boulders rising above the city, each named after the animal it resembles — Elephant Rock (Ethagala), Tortoise Rock, Beetle Rock, and several others. Ethagala, the largest, towers 325 metres above the town with a dagoba and Bo tree on its summit.', 'Ethagala Rock is accessed by stone steps carved into its face, leading to a small dagoba at the summit and sweeping panoramic views across the agricultural plains of the North Western Province. The ancient royal city ruins at Kurunegala — including the Parakramabahu IV palace complex and Embekke Devalaya (famous for its extraordinary woodcarvings) nearby — are among the finest medieval Sinhalese sites.', 'The Embekke Devalaya at Ambakke, 3 km from Kurunegala, is celebrated for its medieval wooden pillars covered in extraordinarily intricate carvings — wrestlers, musicians, dancing girls, mythical beasts, and double-headed eagles — considered the pinnacle of Kandyan woodcarving art. The complex was built by King Vikramabahu III in the 14th century and remains one of the most important decorative art sites in Sri Lanka.', '["historical-monument","Heritage","Archaeological","Medieval","North West"]', 'Ku-ru-ne-ga-la El-e-phant Rock, Eth-a-ga-la', 'Medieval capital, 325-metre Elephant Rock, animal-shaped boulders, Embekke woodcarvings, North Western Province', 7.4833, 80.3667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_embekke_devalaya', 'Embekke Devalaya', 'religious_site', '14th Century AD', 'Embekke Devalaya is a medieval Hindu-Buddhist shrine near Kandy, celebrated for possessing the most exquisite wooden pillar carvings in Sri Lanka. Built by King Vikramabahu III in the 14th century, its open dancing hall (digge) features 126 unique carved pillars depicting wrestlers, swans, soldiers, dancing girls, double-headed eagles, and lions — no two carvings alike — representing the absolute pinnacle of Kandyan decorative woodcarving.', 'The three buildings of the complex — the main shrine, the drummer''s hall, and the dancing hall — are linked by carved wooden screens and pillared walkways. The dancing hall''s roof is supported entirely by its carved wooden pillars without nails or mortar. The craftsmanship shows influences from South Indian decorative traditions blended with distinctly Sinhalese iconography, including the mythical bird Gandhabherunda.', 'Embekke''s carvings are not only artistic masterpieces but also historical documents — they depict medieval Sri Lankan soldiers in armour, royal court figures, and mythological scenes that provide unique evidence of 14th-century Kandyan court culture. The site remains an active shrine, with the annual Embekke Perahera procession drawing large crowds. It is often visited as part of a circuit with the Lankatilaka and Gadaladeniya temples nearby.', '["religious-temple","Heritage","Woodcarving","Hill Country","Medieval"]', 'Em-bek-ke De-va-la-ya', '14th century, 126 unique carved wooden pillars, finest woodcarving Sri Lanka, Kandyan court scenes, no two carvings identical', 7.25, 80.5833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_lankatilaka', 'Lankatilaka Temple', 'religious_site', '14th Century AD', 'Lankatilaka (Ornament of Lanka) is a towering medieval rock temple built by King Bhuvanekabahu IV in 1344 AD on a granite outcrop near Kandy. Its massive brick walls rise 17 metres and shelter a colossal standing Buddha, but its most remarkable feature is the exquisite stone carvings covering every surface — considered equal in quality to the woodcarvings of neighbouring Embekke Devalaya.', 'The image house is built in the Polonnaruwa architectural tradition with towering brick walls, elaborate stucco friezes of elephants, dwarves, and floral patterns, and a superb gateway with guardian figure carvings. The interior houses a damaged but still-impressive 11-metre standing Buddha flanked by Bodhisattva figures, and three Hindu devale shrines within the same compound — reflecting the syncretic nature of medieval Sri Lankan religion.', 'Lankatilaka contains a slab inscription listing the village donors who provided labour and materials for its construction — a rare and detailed historical record of 14th century Sri Lankan village society and the patronage system that built the great temples. The rock on which the temple stands has an ancient cave shelter used by monks for centuries before the current temple was built above it.', '["religious-temple","Buddhist","Heritage","Hill Country","Medieval"]', 'Lan-ka-ti-la-ka Tem-ple', '14th century, Ornament of Lanka, 17-metre brick walls, colossal standing Buddha, donor inscription historical record, Kandy area', 7.2667, 80.5833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_gadaladeniya', 'Gadaladeniya Temple', 'religious_site', '14th Century AD', 'Gadaladeniya Temple, built in 1344 AD by King Bhuvanekabahu IV using a South Indian master architect named Ganesvarachari, is a remarkable fusion of South Indian and Sinhalese architectural traditions. Its main shrine is designed in the South Indian nagara style with a stone sikhara tower — unique in Sri Lanka — yet its surrounding mandapas and subsidiary shrines follow Sinhalese Buddhist conventions.', 'The temple is built on a massive granite outcrop, with the main shrine''s stone tower forming its most distinctive feature — a square-plan tower with horizontal mouldings in South Indian Dravidian style, sitting atop a Sinhalese image house. The courtyard contains a large bo tree sheltered by an elegant pillared canopy, and a free-standing moonstone at the entrance is considered one of the finest examples of the form.', 'Gadaladeniya represents a crucial moment in Sri Lankan architectural history — the deliberate importation of South Indian master craftsmen by Kandyan-era kings, resulting in a creative synthesis rather than mere imitation. The temple is part of the ''Kandy Triangle'' of 14th-century temples — Gadaladeniya, Lankatilaka, and Embekke — that together represent the high point of late medieval Sinhalese religious architecture and craft.', '["religious-temple","Buddhist","Heritage","Architecture","Hill Country"]', 'Ga-da-la-de-ni-ya Tem-ple', '14th century, South Indian stone tower on Sri Lankan temple, master architect Ganesvarachari, finest moonstone entrance, Kandy Triangle', 7.2833, 80.5667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_aluvihara', 'Aluvihara Rock Temple', 'religious_site', '3rd Century BC', 'Aluvihara is one of the most historically significant Buddhist sites in the world — it is where, around 29 BC, Buddhist monks first committed the entire Tripitaka (the complete body of Theravada Buddhist scripture) to writing on palm leaves, ending centuries of oral transmission. The monastery sits within a dramatic cluster of grey granite boulders near Matale, with cave shrines carved into and between the rocks.', 'The cave complex features a series of natural granite boulders between which image houses, stairways, and monastic cells have been constructed over 2,000 years. The caves contain ancient murals in Kandyan style depicting Buddhist cosmology, including vivid scenes of the Buddhist hell realm (Avici) that are among the most dramatic in Sri Lanka. A museum on site houses manuscripts and printing stones.', 'The First Buddhist Council to write down the Pali Canon occurred here in the reign of King Vattagamini Abhaya, marking one of the most pivotal events in the history of world religion. The written Tripitaka became the foundation of Theravada Buddhism across Sri Lanka, Myanmar, Thailand, Cambodia, and Laos — making Aluvihara the indirect source of religious texts guiding over 100 million people today. The monastery continues active scriptural copying traditions.', '["religious-temple","Buddhist","Heritage","UNESCO Tentative","Historical"]', 'A-lu-vi-ha-ra Rock Tem-ple', 'Where Pali scriptures were first written, 29 BC Tripitaka committed to palm leaves, foundation of all Theravada Buddhism, cave murals, Matale', 7.4833, 80.7);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_dunhinda_falls', 'Dunhinda Falls', 'attraction', 'Natural Heritage', 'Dunhinda Falls near Badulla is one of the most majestic waterfalls in Sri Lanka, plunging 64 metres into a deep jungle pool in a narrow gorge. The name ''Dunhinda'' means ''smoky water'' in Sinhala, referring to the dense mist the waterfall generates that perpetually shrouds the gorge in a romantic haze. A 1.5 km jungle trek through ancient forest leads to the viewing point.', 'The waterfall drops in a single powerful column from a narrow rock channel, widening as it falls into a circular pool surrounded by sheer rock walls. The spray radius extends 100 metres, keeping the surrounding forest perpetually wet and supporting an extraordinary density of mosses, ferns, and orchids on the cliff faces. The trail to the falls crosses a suspension bridge over the gorge.', 'Dunhinda Falls is the most visited waterfall in Sri Lanka''s Uva Province and a beloved destination for domestic tourists, particularly during the school holiday season. The surrounding Badulla District is historically significant as a key province of the ancient Ruhunu Kingdom and later the Kandyan Kingdom, with several ancient temples and the Uma Oya river system feeding the falls. The misty gorge has inspired Sinhalese poetry for centuries.', '["urban-park","Nature","Waterfall","Hill Country","Trekking"]', 'Dun-hin-da Falls, Smo-ky Wa-ter Falls', '64-metre misty waterfall, Smoky Water meaning, 1.5 km jungle trek, Badulla, suspension bridge crossing, perpetual mist shroud', 6.9167, 81.0333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_koggala_lake', 'Koggala Lake', 'attraction', 'Natural Heritage / Colonial', 'Koggala Lake is the largest natural lagoon in Sri Lanka, covering 197 hectares between Galle and Ahangama on the south coast. Its calm waters shelter an archipelago of small islands — one of which houses a Buddhist monastery, another a cinnamon island still harvesting the spice that made this coast famous to global traders for 2,000 years. The lake is home to the celebrated Martin Wickramasinghe Folk Museum.', 'The lake shore at Koggala village houses the restored ancestral home of Martin Wickramasinghe — Sri Lanka''s most celebrated novelist — now a folk museum containing thousands of traditional Sri Lankan implements, toys, and household objects documenting village life over the past 200 years. A World War II RAF flying boat base was built at Koggala by the British in 1942, and the runway is now Koggala Airport.', 'Martin Wickramasinghe (1890–1976), whose novels including Gamperaliya defined modern Sinhala literature, was born in Koggala village. His folk museum is one of Sri Lanka''s finest collections of traditional material culture. The lake''s cinnamon island continues a 2,000-year tradition — cinnamon from this coast was traded to ancient Egypt, Rome, and Arabia, and Ceylon cinnamon remains the world''s finest quality, distinct from cheaper cassia varieties.', '["museum","Heritage","South Coast","Nature","Lagoon"]', 'Kog-ga-la Lake', 'Largest natural lagoon Sri Lanka, cinnamon island 2000-year tradition, Martin Wickramasinghe museum, WWII RAF base, monastery island', 5.9833, 80.3333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_zoo_dehiwala', 'National Zoological Gardens Dehiwala', 'attraction', 'British Colonial (1936)', 'The National Zoological Gardens in Dehiwala, established in 1936 during British colonial rule, is one of the oldest and largest zoos in South Asia, covering 11 hectares with over 3,500 animals representing 350 species. It houses Sri Lanka''s national animal — the Sri Lanka elephant — alongside Sri Lanka leopards, mugger crocodiles, and an extensive collection of endemic Sri Lankan birds and reptiles.', 'The zoo''s design reflects its colonial origins with wide tree-lined pathways, Victorian-era animal houses, and landscaped gardens. More recent modernisation has introduced naturalistic enclosures for elephants, big cats, and primates. The dolphin and sea lion show facilities, and the aquarium housing marine species from Sri Lankan coastal waters, are among the most visited sections.', 'Dehiwala Zoo plays an important role in conservation breeding programmes for Sri Lanka''s endangered endemic species, including the purple-faced langur and Sri Lanka leopard. The zoo''s elephant performances — featuring trained Asian elephants demonstrating intelligence and dexterity — have been a controversial but deeply popular attraction for generations of Sri Lankan families. It remains the most visited paid attraction in Colombo.', '["urban-park","Wildlife","Colombo","Family","Conservation"]', 'Na-tion-al Zo-o-lo-gi-cal Gar-dens De-hi-wa-la', '1936 colonial zoo, 3500 animals 350 species, Sri Lanka leopards and elephants, Dehiwala Colombo, largest zoo South Asia', 6.8833, 79.8667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_kanniya_springs', 'Kanniya Hot Springs', 'attraction', 'Ancient (pre-Christian era)', 'Kanniya Hot Springs, located 8 km inland from Trincomalee, consists of seven ancient wells of varying temperature — from lukewarm to near scalding — that have been used for therapeutic bathing and religious purification for over 2,000 years. Hindu tradition associates the springs with the sage Agastya, who is said to have created them by striking the earth with his staff. Each well has a different temperature, a phenomenon science has yet to fully explain.', 'The seven wells are enclosed within a small temple compound with separate bathing enclosures for men and women. Ancient stone carvings around the well rims, partially eroded by centuries of use, display decorative motifs from multiple religious periods. A small Hindu shrine and a Buddhist dagoba stand within the same compound, reflecting the multi-faith significance of the springs.', 'Kanniya''s springs have been used by all communities — Tamil, Sinhala, Muslim, and Veddah — since antiquity, making them a rare site of genuinely shared heritage in Sri Lanka''s often-divided north. Pilgrims perform ritual bathing before visiting the Koneswaram Temple in Trincomalee. The springs'' varying temperatures within a few metres of each other remain a geological curiosity that continues to draw scientific interest alongside devotional visits.', '["religious-temple","Heritage","East Coast","Wellness","Natural Wonder"]', 'Kan-ni-ya Hot Springs Trin-co-ma-lee', 'Seven wells different temperatures, 2000-year history, Agastya legend, multi-faith shared heritage, 8 km from Trincomalee', 8.5833, 81.2167);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_kaudulla', 'Kaudulla National Park', 'national_park', 'Established 2002', 'Kaudulla National Park, established in 2002 around the ancient Kaudulla Tank (3rd century AD), forms a critical wildlife corridor with Minneriya and Girithale sanctuaries — together creating the Elephant Corridor, one of Asia''s most important protected elephant migration routes. Between September and December, when Minneriya Tank levels rise, hundreds of elephants migrate to Kaudulla, making it the premier elephant-watching park of the season.', 'The park is centred on the Kaudulla Tank — an ancient reservoir built by King Mahasena in the 3rd century AD that still functions as an irrigation source after 1,700 years. The tank shores, fringed by tall grasslands, are where the elephant concentrations are most spectacular. The surrounding habitat is typical Sri Lankan dry zone forest with scattered natural clearings.', 'The Elephant Corridor linking Kaudulla, Minneriya, and Wasgamuwa is one of the most important conservation achievements in South Asian wildlife management — a 250 square-kilometre protected zone allowing free movement for one of Asia''s most significant wild elephant populations. The ancient Kaudulla Tank itself is a living monument to Sri Lanka''s hydraulic civilisation, maintaining its function across 1,700 years of continuous use.', '["urban-park","Wildlife","Elephant","Safari","Cultural Triangle"]', 'Kau-dul-la Na-tion-al Park', 'Elephant corridor with Minneriya, 3rd century AD ancient tank, September to December best season, 250 sq km protected zone, Cultural Triangle', 8.15, 80.9);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_piduruthalagala', 'Piduruthalagala Peak', 'attraction', 'Natural Heritage', 'Piduruthalagala, also known as Mount Pedro, is the highest mountain in Sri Lanka at 2,524 metres — significantly higher than Adam''s Peak. Located just outside Nuwara Eliya, it is topped by a government communications installation and is therefore closed to the general public, though its dramatic forested slopes and the cloud forest habitat below the summit can be explored on guided trails.', 'The mountain is clothed in cloud forest and montane grassland up to the communications tower at the summit. The upper slopes shelter endemic montane flora including rare orchids, tree ferns, and dwarf bamboo species found nowhere else in South Asia. The Piduruthalagala Strict Natural Reserve covering its slopes is one of Sri Lanka''s most rigorously protected areas.', 'Despite being the highest point in Sri Lanka, Piduruthalagala is far less known than Adam''s Peak because its summit is inaccessible. Its cloud forest represents the last remnant of upper montane forest in Sri Lanka, sheltering species endemic to the highest elevations. The mountain serves as a water tower for Nuwara Eliya town and a critical refuge for the Sri Lanka highland bird assemblage, including the Sri Lanka bush warbler found only above 1,800 metres.', '["urban-park","Nature","Hill Country","Highest Peak","Endemic Species"]', 'Pi-du-ru-tha-la-ga-la Peak, Mount Pe-dro', 'Highest mountain in Sri Lanka 2524 metres, Mount Pedro, cloud forest, closed summit, endemic highland birds, Nuwara Eliya', 6.9987, 80.7758);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_mahiyangana', 'Mahiyangana Temple', 'religious_site', 'Ancient (pre-3rd Century BC)', 'Mahiyangana is believed to be the oldest Buddhist shrine in Sri Lanka, established during the lifetime of the Buddha himself. According to the Mahavamsa chronicle, the Buddha visited Mahiyangana during his first visit to Sri Lanka, preaching to the Yakkha and Naga tribes. A stupa was built over a handful of his hair relics by the Naga king Maniakkhika immediately after the visit — predating all other Buddhist sites on the island.', 'The current gleaming white dagoba has been enlarged and rebuilt multiple times over 2,500 years, each expansion enshrining the earlier structure within. The innermost core — never excavated — is believed to date to the era of the Buddha. The stupa now stands 30 metres high at the junction of the Mahaweli River and the Badulu Oya, a location of ancient spiritual significance for Veddah communities.', 'Mahiyangana holds unique significance as the first place Buddhism reached Sri Lanka, before the official mission of Mahinda Thero in 247 BC. The Veddah people — Sri Lanka''s indigenous inhabitants — have worshipped at Mahiyangana for millennia, and the site is deeply connected to Veddah origin myths and rituals. Annual Vesak celebrations here attract pilgrims from across the country who recognise it as the birthplace of Sri Lankan Buddhism.', '["religious-temple","Buddhist","Heritage","Pilgrimage","Ancient"]', 'Ma-hi-yan-ga-na Tem-ple', 'Oldest Buddhist shrine Sri Lanka, Buddha visited personally, hair relic stupa, Veddah people connection, predates Mahinda Thero mission', 7.3333, 81);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_haputale', 'Haputale', 'attraction', 'British Colonial', 'Haputale is a dramatic highland ridge town in Sri Lanka''s southern hill country, perched on a narrow ridge at 1,431 metres with valleys falling away precipitously on both sides — giving views south across tea estates all the way to the Sri Lankan coast, and north over the Uva Basin. It is surrounded by some of Sri Lanka''s finest high-grown tea estates and is the access point for Lipton''s Seat and Dambatenne Tea Factory.', 'The town itself is a single main street clinging to the ridge, with the railway station at its centre — the railway line dramatically threading the ridge on an engineered shelf. The surrounding tea estate landscape with its geometric patterns of trimmed bushes, estate bungalows, and factory buildings defines the visual character. The Adisham Bungalow — a 1931 English manor house built by Sir Thomas Lister, now a Benedictine monastery — is a remarkable colonial architectural survivor.', 'Haputale''s Adisham Bungalow, open to visitors on weekends, is one of the finest surviving examples of British country house architecture in Sri Lanka — its rose garden, library, and original period furniture provide an extraordinary window into colonial highland life. The town''s railway, passing through it on spectacular mountain terrain, is part of the Colombo–Badulla line voted one of the world''s great train journeys.', '["historical-monument","Heritage","Tea Country","Hill Country","Viewpoint"]', 'Ha-pu-ta-le', 'Highland ridge town, views to coast and Uva Basin, Adisham colonial mansion monastery, access to Lipton''s Seat, world''s great train journey', 6.7667, 80.95);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_elephant_pass', 'Elephant Pass', 'attraction', 'Ancient to Contemporary', 'Elephant Pass is the narrow land causeway connecting the Jaffna Peninsula to mainland Sri Lanka, historically the only land route into the north. Its name derives from the ancient practice of herding elephants from the mainland through this narrow passage to trading ships in the Jaffna Lagoon. During Sri Lanka''s civil conflict (1983–2009), it was the most strategically contested piece of land in the country, changing hands multiple times in some of the bloodiest battles of the war.', 'The causeway is barely 500 metres wide at its narrowest point, with the Elephant Pass Lagoon and the Palk Strait on either side. A military checkpoint and war memorial now mark the entrance to the Jaffna Peninsula. The remnants of wartime fortifications, bunkers, and memorials from both government forces and LTTE are being gradually preserved as historical sites.', 'Elephant Pass is one of the most symbolically loaded places in Sri Lanka — its control determined political and military dominance of the entire north for over two decades. Today, as a freely passable civilian crossing, it represents Sri Lanka''s post-war reunification more concretely than almost any other location. For Tamil communities driving north, crossing Elephant Pass marks the homecoming to the Jaffna Peninsula; for others, it is a pilgrimage through recent history.', '["historical-monument","Heritage","North Sri Lanka","Civil War History","Causeway"]', 'El-e-phant Pass', 'Narrow causeway to Jaffna Peninsula, ancient elephant trading route, most contested civil war battleground, post-war reunification symbol', 9.5833, 80.3667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_hambantota_salt', 'Hambantota Salt Flats', 'attraction', 'Ancient to Contemporary', 'The Hambantota Salt Flats are a network of shallow evaporation pans on the southeastern coast that have produced sea salt for centuries using solar evaporation — one of Sri Lanka''s oldest industries. The salt pans attract extraordinary flocks of flamingos, wading birds, and migratory shorebirds, creating a landscape of striking visual contrasts — white salt crystals, pink flamingos, and deep blue lagoon waters against the backdrop of the ocean.', 'The salt production system comprises a series of interconnected shallow rectangular pans separated by earthen bunds, fed by tidal seawater through sluice gates. The pans are worked by traditional salt rakers — labourers who rake salt crystals into mounds using long-handled wooden implements, then transport them in woven baskets on their heads to collection points. This process is essentially unchanged from ancient practice.', 'Hambantota''s salt industry is one of the oldest continuously operating industries in Sri Lanka, supplying sea salt to the entire country for centuries. The town of Hambantota itself has undergone dramatic transformation with the construction of a Chinese-funded deep-water port and international cricket stadium, making it a study in rapid modernisation contrasted with ancient traditional industries. The salt flat birdlife, peaking October–March, includes hundreds of greater flamingos migrating from Indian breeding grounds.', '["urban-park","Wildlife","Birdwatching","South Coast","Traditional Industry"]', 'Ham-ban-to-ta Salt Flats', 'Ancient sea salt industry, hundreds of flamingos, traditional salt rakers, southeastern coast, centuries-old unchanged process', 6.12, 81.12);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_viharamahadevi_park', 'Viharamahadevi Park Colombo', 'attraction', 'British Colonial (1859)', 'Viharamahadevi Park is Colombo''s largest and oldest public park, established in 1859 by British Governor Sir Henry Ward as ''Victoria Park.'' Renamed after the legendary Queen Viharamahadevi — mother of King Dutugamunu — at independence in 1948, it covers 13 hectares in the heart of Colombo 7''s leafy district, containing a large seated golden Buddha statue, the National Museum, and the Town Hall.', 'The park features a central ornamental pond, a children''s play area, bandstand, and spectacular flowering trees including the national tree — the iron wood (na tree) and flamboyant red Flamboyant trees. The golden Buddha statue, added after independence, is a prominent landmark visible from the main road. The surrounding Colombo 7 district of colonial-era mansions and government buildings provides an elegant urban context.', 'Viharamahadevi Park is the social lung of Colombo — the gathering place for families, cricket games, Sunday morning joggers, and couples on weekday evenings. Queen Viharamahadevi, for whom it is named, is one of Sri Lanka''s most celebrated heroines — the Sinhalese queen who was offered to the sea as a sacrifice from the south coast and washed ashore at Kelaniya, eventually becoming the mother of the king who united Sri Lanka. Her story is the most romantic in the island''s chronicle tradition.', '["urban-park","Heritage","Colombo","Colonial","Family"]', 'Vi-ha-ra-ma-ha-de-vi Park Co-lom-bo', 'Colombo''s oldest park 1859, Queen Viharamahadevi legend, golden Buddha statue, National Museum adjacent, 13 hectares city centre', 6.9106, 79.8617);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_degalldoruwa', 'Degaldoruwa Cave Temple', 'religious_site', '18th Century AD', 'Degaldoruwa Cave Temple near Kandy is celebrated for its exceptional 18th-century Kandyan-period murals — considered among the finest examples of classical Sinhalese painting in Sri Lanka. The cave temple was built during the reign of King Kirti Sri Rajasinha (1747–1782), the same patron who commissioned the painting of the Dambulla cave murals, and its walls are covered in narrative paintings of the Jataka tales of extraordinary artistic quality.', 'The temple is carved into a granite outcrop above the Mahaweli River, with the cave shrine accessed by a narrow path along the cliff face. The interior walls and ceiling are completely covered in Kandyan-period paintings using natural mineral pigments — red ochre, yellow, green, and white — applied to a lime plaster base. The precision and detail of the figures, particularly in the clothing and facial expressions, represent the pinnacle of Kandyan court painting.', 'Degaldoruwa''s murals are significant not only as art but as historical documents — they depict 18th-century Sri Lankan costume, jewellery, social hierarchy, and royal court scenes in extraordinary detail. The temple is maintained by a small community of resident monks and receives far fewer visitors than Kandy''s main sites, making it one of the most rewarding and undiscovered heritage experiences near the city.', '["religious-temple","Buddhist","Heritage","Murals","Hill Country"]', 'De-gal-do-ru-wa Cave Tem-ple', '18th century Kandyan murals, finest classical Sinhalese painting, King Kirti Sri Rajasinha, cliff-face cave temple, undiscovered Kandy gem', 7.3333, 80.6667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_marble_beach', 'Marble Beach Trincomalee', 'beach', 'Natural Heritage', 'Marble Beach is a pristine, sheltered cove within the former military zone of Trincomalee''s China Bay area, long reserved for navy personnel and recently opened to the public. Its unusually calm, crystal-clear waters and white sand beach — previously protected from all development by its military status — make it one of the cleanest and most beautiful beaches on Sri Lanka''s east coast.', 'The beach is enclosed by forested headlands that block any significant ocean swell, creating an almost pool-like swimming environment. The seafloor is white sand and scattered coral patches visible through the clear water, with reef fish visible from the surface. The navy-maintained beach facility is simple — a small canteen and changing rooms — preserving the undeveloped character.', 'Marble Beach''s decades of protection from civilian use under navy administration have left it in exceptionally pristine condition compared to Sri Lanka''s other popular beaches. Its recent opening to the public is a direct consequence of the post-war normalisation of Trincomalee — a city that spent 26 years as a frontline military zone. The beach represents the restoration of Trincomalee''s natural assets to the Sri Lankan public after a generation of restricted access.', '["beach","East Coast","Swimming","Peaceful","Pristine"]', 'Mar-ble Beach Trin-co-ma-lee', 'Former navy-protected cove, crystal clear calm waters, recently opened to public, pristine post-war beach, Trincomalee east coast', 8.55, 81.25);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_bandarawela', 'Bandarawela', 'attraction', 'British Colonial', 'Bandarawela is a highland town at 1,230 metres in Sri Lanka''s Uva Province, prized for its exceptionally mild climate — average temperatures of 19°C year-round with none of Nuwara Eliya''s chill or Colombo''s heat. Once a British colonial sanitarium retreat, it is surrounded by tea estates producing the distinctive Uva tea — a seasonal tea prized by connoisseurs for its unique menthol character produced only in July–September.', 'The town retains several British colonial-era buildings including the historic Bandarawela Hotel (1893), originally built as a tea estate club and one of the oldest continuously operating hotels in Sri Lanka. The surrounding landscape combines tea estates with vegetable farms, orchards, and wild strawberry patches — producing Sri Lanka''s finest strawberries that are sold roadside throughout the district.', 'Uva tea, produced in the estates surrounding Bandarawela and Haputale, is one of the world''s four classic tea regions alongside Assam, Darjeeling, and China''s Keemun. The Uva season tea — distinguished by its bright orange liquor and distinctive eucalyptus-like menthol finish, produced only when the Cachan wind blows through the valleys in July–September — commands premium prices at the Colombo Tea Auction.', '["historical-monument","Heritage","Tea Country","Hill Country","Colonial"]', 'Ban-da-ra-we-la', 'Perfect climate year-round, Uva tea seasonal menthol character, 1893 colonial hotel, strawberry farms, world classic tea region', 6.8333, 80.9833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_victoria_reservoir', 'Victoria Reservoir', 'attraction', 'Contemporary (1985)', 'Victoria Reservoir, completed in 1985 with British aid and named after Queen Victoria, is the largest hydroelectric dam in Sri Lanka and the country''s most important water resource — storing 722 million cubic metres of water and generating 210 MW of electricity. The reservoir flooded several villages and ancient archaeological sites when it was formed, and many Buddhist temple structures were relocated before the flooding.', 'The Victoria Dam is a concrete double-curvature arch dam standing 122 metres high in the Mahaweli River gorge below Kandy. The reservoir behind it stretches 22 km through spectacular highland scenery surrounded by jungle-covered hills. Boat trips on the reservoir provide access to elephant-rich forest shores, and the dam overlook is one of the most dramatic engineering viewpoints in Sri Lanka.', 'The Victoria-Randenigala-Rantambe hydroelectric complex generates over 50% of Sri Lanka''s electricity during peak season, making it the backbone of national energy security. The reservoir''s shores are within the Victoria-Randenigala-Rantambe Sanctuary, a wildlife area protecting elephants, leopards, and endemic birds. The project displaced 30,000 people from flooded villages — a social legacy that continues to shape Mahaweli region communities.', '["urban-park","Nature","Hill Country","Reservoir","Wildlife"]', 'Vic-to-ria Res-er-voir', 'Sri Lanka''s largest dam, 210 MW hydroelectric, 122-metre arch dam, Mahaweli River, elephant-rich forest shores, national energy backbone', 7.2333, 80.7667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_peradeniya_gardens', 'Royal Botanical Gardens Peradeniya', 'attraction', 'British Colonial (1821)', 'The Royal Botanical Gardens at Peradeniya, established in 1821 on the site of a Kandyan royal garden, is one of the finest botanical gardens in Asia, covering 147 acres in a bend of the Mahaweli River just outside Kandy. The gardens house over 4,000 species of plants including a 60-metre Java Fig tree with an aerial root span of 2,500 square metres — one of the largest trees in Asia.', 'The garden is organised into themed sections including the Orchid House (over 300 orchid species), the Spice Garden, Medicinal Plants collection, a palm avenue stretching 300 metres, the Great Lawn, and the Giant Bamboo grove featuring bamboo stalks up to 30 metres high. The suspension bridge over the Mahaweli River offers dramatic views of the garden from above. Colonial-era glasshouses and a palm house survive from the original British layout.', 'Peradeniya Gardens served as the Allied South East Asia Command headquarters during World War II, with Lord Mountbatten operating from offices within the grounds. The site was chosen for its botanical importance — many medicinal plants fundamental to 20th-century pharmaceutical development were first documented and cultivated here. The gardens also played a key role in establishing Sri Lanka''s tea, rubber, and cinchona (quinine) plantation industries by propagating plant stock.', '["urban-park","Heritage","Colonial","Nature","Hill Country"]', 'Per-a-den-i-ya Bot-an-ic-al Gar-dens', '147 acres, 4000 plant species, 60-metre Java Fig tree, WWII Mountbatten HQ, palm avenue, orchid house, near Kandy', 7.2679, 80.5952);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_ratnapura', 'Ratnapura Gem City', 'attraction', 'Ancient to Contemporary', 'Ratnapura — meaning ''City of Gems'' in Sinhala — is the gem mining capital of Sri Lanka and one of the world''s most prolific sources of precious stones. Blue sapphires, rubies, cat''s eye chrysoberyls, alexandrite, and star sapphires have been mined from the river gravels and alluvial pits around Ratnapura for over 2,000 years. Some of the world''s most famous gemstones — including the Blue Belle of Asia sapphire (392 carats) — originated here.', 'The gem mining in Ratnapura is conducted by traditional open-pit mining in waterlogged alluvial gravels, using wooden frames and rattan baskets to sieve the gem-bearing gravel (illam) through a water-sluicing process unchanged for centuries. The National Gem and Jewellery Authority Museum in Ratnapura displays the extraordinary range of gems found in the region alongside the traditional mining equipment.', 'Sri Lanka''s gem trade has shaped its relationships with the ancient world — Arab, Roman, Chinese, and Indian merchants all traded for Ceylon gems. Marco Polo wrote of Sri Lanka that it had ''the best rubies in the world, likewise sapphires, topazes, amethysts and many other precious stones.'' The Star of India sapphire (563 carats, in the American Museum of Natural History) and the Blue Belle of Asia (392 carats, sold for $17.3 million in 2014) are among the world''s most famous gems from this region.', '["museum","Heritage","Gemstones","Traditional Industry","South Sri Lanka"]', 'Rat-na-pu-ra Gem Ci-ty', 'City of Gems, 2000-year sapphire mining, Star of India sapphire, Blue Belle of Asia, traditional alluvial gem pitting, Marco Polo described', 6.6833, 80.3833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_madu_river', 'Madu River Boat Safari', 'attraction', 'Natural Heritage', 'Madu Ganga is a UNESCO-listed Ramsar Wetland and one of Sri Lanka''s most biodiverse river estuaries, a labyrinthine system of 64 islands, mangrove channels, and lagoons near Balapitiya on the southwest coast. Boat safaris wind through the mangrove corridors, stopping at islands with cinnamon gardens, a Buddhist temple, a fish therapy pool, and a snake farm — creating one of the most unique nature experiences in Sri Lanka.', 'The Madu Ganga estuary covers 915 hectares of mangrove forest interspersed with sandy islands. One island houses the Kothduwa Raja Maha Vihara — a 200-year-old Buddhist temple accessible only by boat. Boat safari operators use traditional dugout canoes and fibre boats to navigate the narrow mangrove channels where the root systems of Rhizophora mangroves arch dramatically into the water.', 'Madu Ganga''s 64 islands sustain communities that have lived entirely on water-based livelihoods for generations — fishing, cinnamon peeling (the traditional craft of stripping cinnamon bark by hand), and boat-building. The estuary is critical habitat for the critically endangered purple-faced langur, water monitors, mugger crocodiles, and over 300 bird species. The fish therapy pools, where small Garra rufa fish nibble dead skin, have become an unexpected tourist attraction.', '["urban-park","Wildlife","Nature","West Coast","Boat Safari"]', 'Ma-du Ri-ver Boat Sa-fa-ri, Ma-du Gan-ga', '64 mangrove islands, UNESCO Ramsar wetland, cinnamon island, Buddhist temple by boat, crocodiles and monkeys, Balapitiya', 6.2333, 80.1183);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_brief_garden', 'Brief Garden', 'attraction', 'British Colonial (1929)', 'Brief Garden is the extraordinary creation of Bevis Bawa — elder brother of the celebrated architect Geoffrey Bawa — who transformed a rubber plantation into one of Asia''s most eclectic private gardens over 50 years from 1929. Unlike Geoffrey''s formal architectural approach, Bevis''s garden is an exuberant, romantic creation filled with sculpture, whimsy, hidden grottos, and surprises — reflecting a larger-than-life personality who entertained royalty and celebrities.', 'The 2.4-hectare garden features interconnected garden rooms — a sculpture terrace, a lawn theatre, jungle paths, a lily pond, and a series of outdoor dining areas. The house at its centre is filled with artwork, eclectic antiques, and portraits of the famous visitors Bevis entertained, including Vivien Leigh, Laurence Olivier, and Roger Moore. The garden has no fixed design plan — it evolved organically through Bevis''s enthusiasm over five decades.', 'Brief Garden represents an extraordinary personal vision — a life''s work of aesthetic expression by a man who shaped the cultural world of mid-20th century Sri Lanka. Bevis Bawa''s garden parties became legendary gatherings of artists, writers, and socialites. The garden is now preserved as a heritage site and is one of Sri Lanka''s most unusual cultural experiences — less a botanical garden than an outdoor autobiography of a remarkable personality.', '["museum","Heritage","Architecture","West Coast","Colonial"]', 'Brief Gar-den, Be-vis Ba-wa', 'Bevis Bawa''s 50-year personal garden masterpiece, sculpture grottos, Vivien Leigh and Roger Moore visited, 1929, rubber plantation transformed', 6.3833, 79.9833);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_muthurajawela', 'Muthurajawela Wetlands', 'national_park', 'Natural Heritage', 'Muthurajawela (meaning ''Great Glittering Marsh'') is Sri Lanka''s largest coastal peat bog and mangrove wetland system, covering 3,072 hectares north of Colombo between Negombo and the capital. A critical ecological buffer protecting Colombo from storm surges and flooding, it is also the largest remaining habitat for the purple-faced langur — one of Sri Lanka''s most endangered primates — within the Western Province.', 'The wetland is navigated by a network of Dutch-era canals built in the 17th century as part of the Negombo-Colombo inland waterway system — many still passable by small boat today. The canals thread through mangrove forests where kingfishers, herons, crocodiles, and water monitors are regularly sighted. A visitor centre at Hamilton Canal provides boat hire and guided wetland tours.', 'Muthurajawela''s Dutch canal network is a living legacy of the Dutch East India Company''s engineering ambition in Ceylon — the canals were built to transport cinnamon and other spices from the interior to Colombo port without using the open sea. The wetland''s ecological services — water filtration, flood protection, carbon sequestration — are valued at billions of rupees annually yet remain largely invisible to the city they protect. Restoration efforts since the 1990s have significantly improved bird diversity.', '["urban-park","Wildlife","West Coast","Wetland","Boat Safari"]', 'Mu-thu-ra-ja-we-la Wet-lands, Great Glit-ter-ing Marsh', 'Largest coastal marsh near Colombo, Dutch colonial canals 17th century, purple-faced langur habitat, crocodiles and kingfishers, flood protection', 7.1167, 79.9167);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_galle_face_green', 'Galle Face Green', 'attraction', 'British Colonial (1859)', 'Galle Face Green is a 500-metre oceanfront promenade in central Colombo, facing the Indian Ocean, established in 1859 by Governor Sir Henry Ward as a public esplanade. It is the most iconic public space in Colombo — the city''s living room — where families fly kites, eat street food, court romance, and gather at sunset with the ocean breeze. Colonial-era hotels including the Galle Face Hotel (1864) — Sri Lanka''s oldest hotel — line its northern end.', 'The Green is a long, narrow strip of manicured lawn and paved esplanade between the Galle Road and the Indian Ocean. The Galle Face Hotel, opened in 1864 and continuously operating for 160 years, anchors the northern end with its grand colonial facade. The southern end transitions to the Colombo Lighthouse and the entrance to Colombo''s commercial port. The sea wall along the Green takes the brunt of the Indian Ocean southwest monsoon each May–September.', 'Galle Face Green has been the social heartbeat of Colombo for over 160 years, hosting everything from colonial horse races and cricket matches to political rallies and the extraordinary ''Aragalaya'' protest movement of 2022. Sri Lanka''s most famous street food — isso wade (prawn fritters), kotthu roti, and locally made ice cream — is sold from vendors who have worked the promenade for generations. The sunset view from Galle Face, with dhow silhouettes against the Indian Ocean, is one of South Asia''s great urban spectacles.', '["historical-monument","Heritage","Colombo","Urban","Ocean Front"]', 'Gal-le Face Green Co-lom-bo', 'Colombo''s iconic oceanfront, 1859 colonial promenade, Galle Face Hotel 1864 oldest hotel, kite flying street food, Indian Ocean sunset views', 6.9218, 79.8467);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_pettah', 'Pettah Market Colombo', 'attraction', 'Dutch Colonial / British Colonial', 'Pettah is Colombo''s oldest and most vibrant commercial district, an intense, colourful maze of street markets where every commodity is traded on dedicated streets — electronics on one lane, fabrics on the next, spices, hardware, watches, and flowers each with their own territory. The name derives from the Tamil word ''pettai'' meaning ''outside the fort,'' as this district grew outside the colonial Fort walls.', 'Pettah''s streetscape is a layered architectural palimpsest — Dutch colonial warehouses converted to shops, Victorian-era arcaded commercial buildings, art-deco facades, and modern concrete structures all coexisting in chaotic vitality. The Jami Ul-Alfar Mosque (1909), also called the Red Mosque for its striking candy-striped exterior, is the district''s most distinctive landmark. The Old Dutch Period Museum occupies a 1780 Dutch colonial mansion.', 'Pettah is where all of Sri Lanka''s communities meet in commerce — Tamil traders, Sinhalese wholesalers, Moor (Muslim) gem dealers, Burgher antique sellers, and Malay spice merchants all trade within blocks of each other, creating a commercial ecology unchanged in its essentials since the Portuguese era. The Manning Market (wholesale vegetable market) and Manning Place (fish market) are authentic Sri Lankan commercial experiences of extraordinary sensory intensity.', '["historical-monument","Heritage","Colombo","Market","Urban"]', 'Pet-tah Mar-ket Co-lom-bo', 'Colombo''s oldest market district, candy-striped Red Mosque 1909, Dutch colonial museum, every commodity on dedicated streets, multi-community commerce', 6.9369, 79.8575);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_parliament', 'Parliament of Sri Lanka', 'monument', 'Contemporary (1982)', 'Sri Lanka''s Parliament building, completed in 1982 and designed by architect Geoffrey Bawa, is widely regarded as his greatest work — an extraordinary fusion of traditional Sri Lankan architecture with modernist spatial principles, set on an island in the Diyawanna Oya lake in Sri Jayawardenepura Kotte. The building''s design is so accomplished that it appears simultaneously ancient and entirely modern.', 'The complex occupies a 6-hectare island reached by a ceremonial causeway. Bawa''s design draws on the tradition of the Kandyan-era audience halls — open-sided, pavilion-based buildings with massive overhanging copper roofs — but interprets them through a modernist lens of precise geometry and spatial drama. The copper-clad roofs have weathered to a distinctive blue-green patina. The surrounding lake and landscaped grounds integrate the building seamlessly into the landscape.', 'Geoffrey Bawa''s Parliament is considered one of the great public buildings of the 20th century in Asia, earning international recognition as a building that proves traditional forms can be authentically reinterpreted for modern democratic institutions. Sri Jayawardenepura Kotte — the suburb where the Parliament is located — was the ancient capital of the Kotte Kingdom (15th–16th centuries), making the choice of location a statement of historical continuity.', '["historical-monument","Heritage","Colombo","Architecture","Modern"]', 'Par-lia-ment of Sri Lan-ka, Sri Ja-ya-war-de-na-pu-ra Kot-te', 'Geoffrey Bawa''s masterpiece 1982, island in lake, Kandyan pavilion modernist fusion, copper roof, one of Asia''s great public buildings', 6.8878, 79.8878);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_kosgoda_turtle', 'Kosgoda Sea Turtle Conservation', 'attraction', 'Natural Heritage / Conservation', 'Kosgoda on Sri Lanka''s southwest coast is home to one of the oldest sea turtle conservation projects in Asia, established in 1981. The Kosgoda Turtle Hatchery rescues eggs from nesting turtles on the beach, incubates them in protected sandy pits, and releases thousands of hatchlings each year. Five species of sea turtle nest on this stretch of coast, and the hatchery allows visitors to observe hatchlings up close before their ocean release.', 'The hatchery consists of a beachside compound with incubation pits — sandy enclosures fenced with wire mesh — holding thousands of eggs at various stages of development. Holding tanks contain injured adult turtles undergoing rehabilitation. The facility is deliberately simple, prioritising function over aesthetics, with staff on round-the-clock patrol of the adjacent nesting beach.', 'Kosgoda''s turtle conservation work began long before eco-tourism was a recognised concept — founded by a local businessman who recognised the crisis facing turtle populations from egg collection and habitat loss. The project has released over 1 million hatchlings since 1981. Kosgoda was severely affected by the 2004 tsunami, which destroyed the original hatchery — the rebuilt project became a symbol of community resilience, funded partly by international post-tsunami aid.', '["urban-park","Wildlife","Conservation","West Coast","Marine"]', 'Kos-go-da Sea Tur-tle Con-ser-va-tion', '1981 oldest turtle project in Asia, 1 million hatchlings released, five turtle species, hands-on hatchling experience, post-tsunami symbol', 6.2333, 80.0333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_nelligala', 'Nelligala International Buddhist Centre', 'religious_site', 'Contemporary', 'Nelligala International Buddhist Centre sits on a hillside outside Kandy with stunning panoramic views of the Kandy city and surrounding highland valley. The centre features a large white stupa visible from across the Kandy basin, a meditation hall accommodating international retreatants, and a serene garden pathway to the summit. It represents a modern expression of Sri Lanka''s living Theravada Buddhist tradition.', 'The complex is built on a series of hillside terraces, with a striking white dagoba at the summit connected by a covered pilgrim path. The image house and meditation halls are built in modern adaptations of the Kandyan architectural tradition — white walls, terracotta tile roofs, and timber-screened verandas. The 360-degree view from the dagoba terrace encompasses the entire Kandy basin.', 'Nelligala serves both as an active monastic centre and as an international meditation retreat facility, hosting practitioners from across Asia, Europe, and North America. Its hilltop position with unobstructed views of the central highlands creates an environment of unusual tranquillity within sight of Sri Lanka''s most sacred city. The white stupa, lit at night, is visible from Kandy town as a serene landmark above the city.', '["religious-temple","Buddhist","Hill Country","Meditation","Viewpoint"]', 'Nel-li-ga-la In-ter-na-tion-al Bud-dhist Cen-tre', 'Hilltop stupa with panoramic Kandy views, international meditation retreats, modern Theravada centre, night-lit dagoba, outside Kandy', 7.2833, 80.6333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_somawathiya', 'Somawathiya National Park', 'national_park', 'Established 1986', 'Somawathiya National Park in northeastern Sri Lanka combines extraordinary wildlife habitat with one of the most sacred Buddhist sites in the country — the Somawathiya Chaitya stupa, believed to enshrine the right tooth of the Buddha. The park protects a critical elephant corridor along the Mahaweli River and is home to large herds of wild elephants, leopards, sloth bears, and hundreds of bird species.', 'The Somawathiya Chaitya, a gleaming white stupa situated on the banks of the Mahaweli River, dates to the 2nd century BC and was built by King Kavantissa to house the tooth relic. The stupa''s riverside location creates a uniquely atmospheric pilgrimage experience, with wild elephants sometimes visible from the temple grounds across the river. The surrounding park is dry zone jungle with riverine forest along the Mahaweli.', 'Somawathiya is one of the 16 sacred places (Solosmasthana) in Sri Lanka''s Buddhist pilgrimage tradition — sites specifically blessed by the Buddha during his visits to the island. The Poson Poya full moon festival in June brings tens of thousands of pilgrims to Somawathiya, many travelling on foot for days from across the country in the ancient tradition of pilgrimage walking. The combination of sacred site and wildlife creates an experience found nowhere else in Sri Lanka.', '["religious-temple","Buddhist","Wildlife","Heritage","North East"]', 'So-ma-wath-i-ya Na-tion-al Park', 'Sacred Buddhist stupa 2nd century BC, Buddha tooth relic, elephants visible from temple, Poson Poya pilgrimage, 16 sacred places of Sri Lanka', 8, 81.1667);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_maduru_oya', 'Maduru Oya National Park', 'national_park', 'Established 1983', 'Maduru Oya National Park in eastern Sri Lanka, established in 1983 to protect the catchment of the Maduru Oya Reservoir, is one of the four national parks constituting the Mahaweli development zone conservation network. It is home to one of the highest concentrations of wild elephants in Sri Lanka and shelters the last remaining community of Veddah people — Sri Lanka''s indigenous forest-dwellers — within its boundaries.', 'The park''s terrain is predominantly dry zone mixed forest with several ancient irrigation tanks within its boundaries. The Maduru Oya reservoir, constructed as part of the Accelerated Mahaweli Programme, provides permanent water that attracts wildlife year-round. Ancient ruins of the Mahakanadarawa irrigation complex within the park reveal centuries of human habitation before the area was gazetted as protected land.', 'The Veddah communities of Maduru Oya — the Dambana Veddah — are the direct descendants of Sri Lanka''s pre-Sinhalese inhabitants, maintaining a forest culture that predates the arrival of the Indo-Aryan settlers 2,500 years ago. Their traditional knowledge of forest plants, honey-gathering, and tracking is increasingly recognised as irreplaceable cultural heritage. The park''s protection simultaneously protects both biodiversity and the living indigenous culture of Sri Lanka''s original people.', '["urban-park","Wildlife","Elephant","Indigenous Culture","East Sri Lanka"]', 'Ma-du-ru O-ya Na-tion-al Park', 'Highest elephant concentration, last Veddah indigenous community within park, Mahaweli reservoir, ancient irrigation ruins, eastern Sri Lanka', 7.7, 81.1333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_okanda', 'Okanda Beach and Temple', 'attraction', 'Ancient / Natural Heritage', 'Okanda is a remote, pristine beach and ancient Hindu temple at the southern entrance of Kumana National Park on Sri Lanka''s far east coast. The Okanda Devalaya — a small but powerful temple dedicated to Skanda — is the departure point for the Pada Yatra: the ancient annual pilgrimage on foot from Jaffna to Katharagama, a 500-km walk of 4–6 weeks undertaken by thousands of Tamil Hindu devotees every year.', 'The Okanda Devalaya is a modest coastal temple of whitewashed walls and a simple gopuram entrance, positioned dramatically at the edge of the jungle where it meets the beach. The beach itself is wild and undeveloped, accessible only by 4WD through Kumana National Park — requiring a safari to reach the pilgrimage temple. The surrounding coastal forest is prime habitat for leopards, elephants, and sea turtles.', 'The Pada Yatra pilgrimage through Okanda is one of Asia''s most extraordinary religious journeys — pilgrims travel barefoot through jungle, cross rivers, and walk along remote beaches for 4–6 weeks from Jaffna to Katharagama. The journey was suspended during the civil conflict and its revival post-2009 was a powerful symbol of reconciliation, with Tamil pilgrims crossing regions of the country they had not visited in decades. Okanda is where sea-crossing pilgrims land and begin the final southern leg of the journey.', '["religious-temple","Hindu","Beach","East Coast","Pilgrimage"]', 'O-kan-da Beach and Tem-ple', 'Pada Yatra pilgrimage start point, 500 km barefoot walk Jaffna to Katharagama, remote jungle beach, Skanda temple, Kumana Park entrance', 6.6167, 81.8);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_trincomalee_bay', 'Trincomalee Bay', 'attraction', 'Ancient to Contemporary', 'Trincomalee Bay is one of the finest natural deep-water harbours in the world — a vast sheltered bay of extraordinary beauty that has shaped the history of maritime Asia for over 2,000 years. Ancient Tamil and Sinhalese kingdoms, Arab traders, Portuguese, Dutch, British, and Japanese military commanders all recognised its strategic supremacy. Napoleon called it ''the finest harbour in the world; whoever holds Trincomalee holds the Indian Ocean.''', 'The bay''s geography is defined by three major promontories — Swami Rock (topped by Koneswaram Temple and Fort Frederick), Ostenburg Point, and China Bay — that create a sheltered anchorage of extraordinary scale. The harbour is deep enough to accommodate the largest modern vessels. Its shores include Nilaveli and Uppuveli beaches to the north, Marble Beach within the former military zone, and the historic town of Trincomalee itself with its Dutch-era buildings.', 'Trincomalee Bay''s historical significance spans 2,000 years of maritime history. The Battle of Ceylon in April 1942 — when Japanese aircraft attacked Trincomalee and sank HMS Hermes — was a pivotal moment in World War II. The harbour''s waters contain some of Asia''s finest wreck diving, including HMS Hermes at 60 metres depth. Post-war, Trincomalee has emerged as eastern Sri Lanka''s tourism centrepiece, its harbour offering whale watching, snorkelling, diving, and coastal cruises.', '["historical-monument","Heritage","East Coast","Harbour","Maritime"]', 'Trin-co-ma-lee Bay', 'World''s finest natural harbour, Napoleon''s quote, WWII HMS Hermes sunk, 2000-year strategic history, whale watching and wreck diving', 8.5667, 81.2333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_alankuda', 'Alankuda Beach', 'beach', 'Natural Heritage', 'Alankuda is a secluded beach on the Kalpitiya Peninsula, a thin sandy spit on Sri Lanka''s northwest coast where the Indian Ocean meets the Puttalam Lagoon. The beach is surrounded by some of the finest kite surfing conditions in Asia — with consistent trade winds from November to April — and the waters offshore host regular sightings of spinner dolphins and blue whales. The peninsula''s isolation has preserved it as one of Sri Lanka''s most pristine beach environments.', 'Alankuda''s beach setting is defined by its extraordinary narrowness — the peninsula is sometimes only 200 metres wide, with lagoon on one side and ocean on the other, creating a unique dual waterfront experience. The accommodation is dominated by small eco-lodges built from natural materials with minimal environmental footprint. The surrounding lagoon shoreline is fringed with mangroves sheltering flamingos, pelicans, and wading birds.', 'Alankuda and the Kalpitiya Peninsula have become central to Sri Lanka''s emerging eco-tourism identity — offering experiences that combine world-class kite surfing, whale and dolphin watching, snorkelling over Bar Reef Marine Sanctuary, and flamingo watching in Puttalam Lagoon. The area''s development has provided economic alternatives for fishing communities whose traditional catches have declined due to overfishing, making it a model for community-based coastal tourism.', '["beach","Wildlife","West Coast","Kite Surfing","Eco Tourism"]', 'A-lan-ku-da Beach, Kal-pi-ti-ya', 'World-class kite surfing, lagoon and ocean both sides, spinner dolphins, flamingos in lagoon, pristine northwest peninsula, eco-lodges', 8.28, 79.77);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_mullaitivu', 'Mullaitivu Coast', 'beach', 'Natural Heritage / Contemporary History', 'Mullaitivu is a remote district on Sri Lanka''s northern coast, once the heartland of LTTE (Liberation Tigers of Tamil Eelam) territory and the site of the final battle of the civil war in May 2009. Today the area is gradually opening to tourism, revealing a coastline of extraordinary wild beauty — long, empty beaches, a lagoon system, and the Nandikadal Lagoon where the conflict finally ended. A civil war museum and war memorials are emerging as sites of remembrance.', 'The coastline features unbroken stretches of white sand beach, some extending for tens of kilometres with no development, backed by coconut palms and scrub jungle. The Nandikadal Lagoon — the narrow strip of water where the final phase of the civil war was fought — is surrounded by memorials and former military positions. A sunken LTTE vessel is visible on the beach as an accidental war monument.', 'Mullaitivu''s coast carries immense emotional weight for Sri Lanka''s Tamil community — it is where tens of thousands of civilians were trapped during the final offensive. The site is the subject of ongoing debate about memorialisation, accountability, and reconciliation. The area''s natural beauty — long considered among the finest unspoilt coastline in South Asia — has been largely preserved by decades of restricted access, making it simultaneously a place of tragedy and natural splendour.', '["beach","Heritage","North Sri Lanka","Civil War History","Untouched"]', 'Mul-lai-ti-vu Coast', 'Final civil war battleground 2009, wild untouched northern beaches, Nandikadal Lagoon, emerging reconciliation tourism, extraordinary unspoilt coastline', 9.2667, 80.8167);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_puttalam_lagoon', 'Puttalam Lagoon', 'attraction', 'Natural Heritage', 'Puttalam Lagoon is Sri Lanka''s largest coastal lagoon, covering 16,000 hectares of brackish water, mangrove channels, and tidal flats on the northwest coast. It is a critically important habitat for migratory waterbirds from the Palearctic region, supports the largest prawn and fish farming industry in Sri Lanka, and is the economic lifeline for over 50 traditional fishing villages around its shores.', 'The lagoon''s landscape is defined by an intricate network of mangrove-fringed channels, open water expanses, and salt-encrusted mudflats. The town of Puttalam at its northern end features a Dutch-era watchtower and colonial church. Traditional fishing boats — outrigger canoes (oruwa) and fibre trawlers — work the lagoon waters alongside modern prawn farms enclosed by earthen bunds.', 'Puttalam Lagoon is one of Sri Lanka''s most important fisheries, supporting communities that have worked its waters for over a millennium. The Muslim fishing communities of Puttalam — some of the oldest Muslim settlements in Sri Lanka, with Arab trading origins dating to the 8th century — maintain distinct cultural traditions including unique fishing boat designs and food culture. The lagoon''s flamingo and pelican flocks create extraordinary wildlife spectacles accessible by local fishing boat.', '["urban-park","Wildlife","West Coast","Birdwatching","Lagoon"]', 'Put-ta-lam La-goon', 'Largest coastal lagoon Sri Lanka, flamingos and pelicans, 8th century Arab Muslim fishing communities, prawn farming industry, migratory waterbirds', 8.0333, 79.8333);
INSERT INTO places (location_id, name, category, era, summary, architectural_details, cultural_significance, tags_json, tts_pronunciation, tts_key_facts, lat, lng) VALUES ('lk_navix_jaffna_peninsula_beaches', 'Casuarina Beach Jaffna', 'beach', 'Natural Heritage', 'Casuarina Beach on the Jaffna Peninsula is one of northern Sri Lanka''s finest beaches — a long stretch of white sand fringed by casuarina (ironwood) trees on the shore of the Palk Strait, with extraordinarily calm, shallow water extending hundreds of metres. Reopened to tourism after decades of civil conflict, it is rapidly becoming the most popular beach in northern Sri Lanka for Tamil families and adventurous visitors from the south.', 'The beach derives its name from the dense casuarina tree planting along the shore — the signature coastal tree of northern Sri Lanka, whose feathery needles create a distinctive shade canopy. The shallow, clear water over a sandy seabed is safe for family swimming for hundreds of metres from shore. Simple beach restaurants serving Jaffna-style seafood — crab curry, mutton rolls, and palmyra fruit dishes — line the shore.', 'Casuarina Beach represents the normalisation of northern Sri Lanka''s tourist economy after the civil war''s end in 2009. The Jaffna Peninsula''s beaches were entirely closed to outsiders for over 25 years, making them among the least explored coastlines of South Asia. The beach is also a point of cultural exchange — southern Sinhalese visitors encounter Jaffna''s distinct Tamil food culture, architecture, and social customs in a setting of natural beauty that encourages genuine cross-cultural contact.', '["beach","North Sri Lanka","Swimming","Peaceful","Post-War"]', 'Ca-su-a-ri-na Beach Jaf-fna', 'Finest beach north Sri Lanka, shallow calm water, casuarina shade trees, Jaffna seafood, post-war tourism, 25 years inaccessible', 9.8, 79.9833);
